window.BANQUE_INFINI = {"module":"annee-1/theorique/semestre-2/physio","titre":"Physiologie II","sources":[{"t":"Cours 1 — Système Digestif","q":"qcm/qcm-1-systeme-digestif.html","f":"fiches/fiche-1-systeme-digestif.html"},{"t":"Cours 2 — Système Urinaire","q":"qcm/qcm-2-systeme-urinaire.html","f":"fiches/fiche-2-systeme-urinaire.html"},{"t":"Cours 3 — Équilibre Acido-Basique","q":"qcm/qcm-3-equilibre-acido-basique.html","f":"fiches/fiche-3-equilibre-acido-basique.html"},{"t":"Cours 4 — Système Reproducteur","q":"qcm/qcm-4-systeme-reproducteur.html","f":"fiches/fiche-4-systeme-reproducteur.html"},{"t":"Cours 5 — Physiologie de l'Exercice","q":"qcm/qcm-5-physio-exercice.html","f":"fiches/fiche-5-physio-exercice.html"},{"t":"Cours 6 — Physio de la Vie Quotidienne","q":"qcm/qcm-6-physio-vie-quotidienne.html","f":"fiches/fiche-6-physio-vie-quotidienne.html"}],"questions":[{"q":"Quel est l'ordre correct du tube digestif ?","o":["Bouche → Œsophage → Estomac → Intestin grêle → Gros intestin → Anus","Bouche → Estomac → Œsophage → Gros intestin → Intestin grêle → Anus","Bouche → Pharynx → Estomac → Intestin grêle → Œsophage → Anus","Bouche → Œsophage → Intestin grêle → Estomac → Gros intestin → Anus"],"r":0,"e":"Le trajet correct : Bouche → Pharynx → Œsophage → Estomac → Intestin grêle (duodénum, jéjunum, iléon) → Gros intestin (cæcum, côlon, rectum, canal anal) → Anus.","s":0},{"q":"Combien de fonctions principales le système digestif assure-t-il ?","o":["6","7","8","10"],"r":2,"e":"8 fonctions : Ingestion, Mastication, Propulsion, Mélange, Sécrétion, Digestion, Absorption, Élimination.","s":0},{"q":"Quel est le pH normal de l'estomac ?","o":["6,8 – 7,5","5,6 – 8,0","7,2 – 7,5","1,5 – 2,0"],"r":3,"e":"L'estomac est très acide (1,5–2,0) grâce à l'HCl des cellules pariétales. Cela dénature les protéines et active la pepsine.","s":0},{"q":"Quelles sont les 3 paires de glandes salivaires ?","o":["Sublinguale, parotide, submandibulaire","Pinéale, hypophysaire, thyroïde","Surrénale, mammaire, gastrique","Thymus, rate, foie"],"r":0,"e":"Les 3 paires sont : sublinguale (sous la langue), submandibulaire (sous la mâchoire) et parotide (devant l'oreille).","s":0},{"q":"Quelles sont les 3 parties de l'intestin grêle ?","o":["Cæcum, côlon, rectum","Duodénum, jéjunum, iléon","Œsophage, estomac, pylore","Pharynx, larynx, trachée"],"r":1,"e":"L'intestin grêle se divise en duodénum (1ère partie), jéjunum (milieu) et iléon (dernière partie). Le gros intestin contient cæcum, côlon, rectum, canal anal.","s":0},{"q":"Quel organe sécrète la bile ?","o":["Pancréas","Vésicule biliaire","Foie","Estomac"],"r":2,"e":"Le foie produit la bile (600–1000 ml/jour). La vésicule biliaire ne fait que la stocker et la concentrer avant de la libérer dans le duodénum.","s":0},{"q":"Quel est le rôle principal de la mastication ?","o":["Sécréter des enzymes","Broyer les aliments par les dents","Absorber les nutriments","Stocker les aliments"],"r":1,"e":"La mastication = broyage des aliments par les dents dans la bouche. Elle augmente la surface de contact pour les enzymes.","s":0},{"q":"Le bolus est :","o":["Un type d'enzyme","La masse alimentaire après mastication imprégnée de salive","Le contenu acide de l'estomac","Une vésicule du pancréas"],"r":1,"e":"Le bolus (ou bol alimentaire) est la masse formée dans la bouche après mastication et imprégnation salivaire. Il devient chyme dans l'estomac.","s":0},{"q":"Quelle est la définition du chyme ?","o":["Le bol alimentaire dans la bouche","Le mélange aliments + sécrétions gastriques","Les selles","Une enzyme pancréatique"],"r":1,"e":"Le chyme est le mélange semi-liquide formé dans l'estomac par l'action des sécrétions gastriques (HCl + pepsine + mucus) sur le bol alimentaire.","s":0},{"q":"Quelle enzyme commence la digestion des glucides dans la bouche ?","o":["Pepsine","Amylase salivaire","Lipase linguale","Lactase"],"r":1,"e":"L'amylase salivaire (ptyaline) débute la dégradation de l'amidon en maltose dans la cavité orale.","s":0},{"q":"Pendant quelle phase les sécrétions gastriques sont-elles INHIBÉES ?","o":["Phase céphalique","Phase gastrique","Phase intestinale","Phase orale"],"r":2,"e":"La phase intestinale inhibe les sécrétions gastriques quand le pH < 2 ou que des lipides arrivent au duodénum (via sécrétine, CCK, GIP).","s":0},{"q":"Pendant la phase céphalique des sécrétions gastriques, le stimulus est :","o":["La distension de l'estomac","Le goût, l'odorat et les souvenirs (via nerf vague)","La présence de chyme dans le duodénum","Le pic de gastrine"],"r":1,"e":"La phase céphalique est déclenchée par le goût, l'odorat, la vue ou les souvenirs d'aliments → stimulation gastrique via le nerf vague (X).","s":0},{"q":"Pendant la phase gastrique, le facteur déclenchant principal est :","o":["Le sommeil","La présence d'aliments dans l'estomac (distension + chémorécepteurs → gastrine)","La marche","Les odeurs"],"r":1,"e":"La phase gastrique est déclenchée par la distension de l'estomac et les chémorécepteurs → libération de gastrine → ↑ HCl et pepsinogène.","s":0},{"q":"Quel est le rôle principal de la veine porte hépatique ?","o":["Transporter le sang oxygéné vers le foie","Drainer le sang du foie vers le cœur","Acheminer les nutriments absorbés vers le foie pour traitement","Transporter la bile vers le duodénum"],"r":2,"e":"La veine porte hépatique transporte les nutriments absorbés au niveau intestinal vers le foie qui les traite avant la circulation systémique.","s":0},{"q":"Quelles enzymes pancréatiques digèrent les protéines ?","o":["Amylase, Maltase, Sucrase","Lipase, Phospholipase, Cholestérolestérase","Trypsine, Chymotrypsine, Carboxypeptidase","Nucléases, DNase, RNase"],"r":2,"e":"Trypsine, chymotrypsine et carboxypeptidase sont les enzymes protéolytiques pancréatiques (sécrétées en zymogènes inactifs).","s":0},{"q":"Quelle est la différence entre bolus et chyme ?","o":["Le bolus est liquide, le chyme est solide","Le bolus se forme dans la bouche, le chyme dans l'estomac","Le bolus contient des enzymes, le chyme non","Aucune différence"],"r":1,"e":"Le bolus = bol alimentaire formé dans la bouche après mastication. Le chyme = mélange semi-liquide formé dans l'estomac.","s":0},{"q":"Quelle est la fonction principale du sphincter pylorique ?","o":["Empêcher le reflux acide vers l'œsophage","Contrôler la vidange progressive du chyme vers le duodénum","Sécréter de la bile","Absorber l'eau"],"r":1,"e":"Le sphincter pylorique partiellement fermé permet la vidange progressive (pompe pylorique) : chaque contraction péristaltique gastrique envoie un peu de chyme vers le duodénum.","s":0},{"q":"Quel est le rôle de la gastrine ?","o":["Inhiber la sécrétion gastrique","Stimuler la sécrétion d'HCl et de pepsinogène par l'estomac","Émulsifier les graisses","Digérer l'amidon"],"r":1,"e":"La gastrine, libérée pendant la phase gastrique, stimule la sécrétion d'HCl et de pepsinogène par l'estomac, ainsi que la motilité gastrique.","s":0},{"q":"Le facteur intrinsèque sécrété par l'estomac est nécessaire à l'absorption :","o":["De la vitamine A","Du fer","De la vitamine B12","Du calcium"],"r":2,"e":"Le facteur intrinsèque (sécrété par les cellules pariétales) est indispensable à l'absorption de la vitamine B12 dans l'iléon. Son absence cause une anémie pernicieuse.","s":0},{"q":"L'émulsification des lipides est réalisée par :","o":["La pepsine","Les sels biliaires","L'amylase pancréatique","L'HCl gastrique"],"r":1,"e":"Les sels biliaires (dans la bile) émulsifient les grosses gouttelettes lipidiques en micelles → augmente la surface d'action des lipases pancréatiques.","s":0},{"q":"Quel pourcentage d'eau est absorbé dans l'intestin grêle ?","o":["50%","70%","92%","99%"],"r":2,"e":"L'intestin grêle absorbe ~92% de l'eau. Le gros intestin en absorbe 6–7%, et seulement ~1% est éliminé dans les selles.","s":0},{"q":"Les ondes péristaltiques gastriques sont caractérisées par :","o":["Une fréquence de 20 sec, faibles","Une fréquence d'environ 3/min, fortes","Aucune contraction","Des contractions circulaires uniquement"],"r":1,"e":"Les ondes péristaltiques sont des contractions plus fortes (que les ondes de mélange) survenant ~3 fois/min, propulsant le chyme vers le pylore.","s":0},{"q":"Les mouvements de masse du gros intestin surviennent :","o":["1 fois/min","1 fois/heure","3 à 4 fois/jour","Une fois par semaine"],"r":2,"e":"Les mouvements de masse (contractions puissantes propulsant le contenu colique vers le rectum) surviennent 3 à 4 fois par jour, souvent après les repas.","s":0},{"q":"Le suc pancréatique se compose de :","o":["Composant aqueux (Na⁺, K⁺) + composant enzymatique","Bile uniquement","Acide chlorhydrique","Mucus uniquement"],"r":0,"e":"Le suc pancréatique a 2 composants : aqueux (Na⁺, K⁺ ≈ LEC, neutralise l'acidité) et enzymatique (trypsine, chymotrypsine, amylase, lipase, nucléases).","s":0},{"q":"Par quelle voie les chylomicrons sont-ils absorbés ?","o":["Veine porte hépatique","Vaisseaux lymphatiques (lactéals)","Capillaires sanguins de la muqueuse","Diffusion directe vers le foie"],"r":1,"e":"Les chylomicrons sont trop volumineux pour les capillaires sanguins. Ils empruntent les lactéals (vaisseaux lymphatiques des villosités) → canal thoracique → veine sous-clavière gauche.","s":0},{"q":"À quelle structure correspond la « pompe pylorique » ?","o":["Un muscle qui propulse le chyme dans l'estomac","Le mécanisme de vidange progressive du chyme vers le duodénum (sphincter pylorique partiellement fermé)","Une pompe à protons gastrique","Le sphincter œsophagien inférieur"],"r":1,"e":"La pompe pylorique = mécanisme par lequel le sphincter pylorique partiellement fermé laisse passer une petite quantité de chyme à chaque contraction péristaltique gastrique.","s":0},{"q":"Le GIP (Gastric Inhibitory Peptide) :","o":["Stimule la sécrétion gastrique","Inhibe les sécrétions et la motilité gastriques + stimule l'insuline","Provoque la contraction vésiculaire","N'existe pas"],"r":1,"e":"Le GIP, libéré par le duodénum en réponse à du glucose et aux lipides, inhibe les sécrétions et la motilité gastriques, et stimule la libération d'insuline (effet incrétine).","s":0},{"q":"Quel transport est utilisé pour l'absorption du glucose dans l'entérocyte ?","o":["Diffusion simple uniquement","Cotransport SGLT1 avec Na⁺ (apical) puis GLUT2 (basolatéral)","Transport actif primaire ATP-dépendant uniquement","Endocytose"],"r":1,"e":"Le glucose est absorbé via SGLT1 (cotransport actif secondaire avec Na⁺) au pôle apical, puis sort vers la circulation par GLUT2 (diffusion facilitée) au pôle basolatéral.","s":0},{"q":"Quelle est la séquence enzymatique correcte pour digérer les protéines ?","o":["Pepsine (estomac) → trypsine/chymotrypsine/carboxypeptidase (pancréas) → aminopeptidases (intestin)","Amylase → lipase → trypsine","Lactase → maltase → sucrase","Pepsine uniquement"],"r":0,"e":"Cascade : Pepsine (estomac, pH acide) commence → trypsine, chymotrypsine, élastase, carboxypeptidase (pancréas) continuent → aminopeptidases et dipeptidases (intestin) finissent → AA, di- et tripeptides absorbés.","s":0},{"q":"Pourquoi la vésicule biliaire concentre-t-elle la bile ?","o":["Elle ajoute des sels biliaires","Elle réabsorbe l'eau (bile concentrée 5–10×)","Elle ajoute du cholestérol","Elle dilue les enzymes"],"r":1,"e":"La vésicule biliaire réabsorbe activement l'eau et les ions, concentrant les sels biliaires 5 à 10 fois. Cela permet de stocker une grande capacité émulsifiante dans un petit volume.","s":0},{"q":"Le pH normal du duodénum est :","o":["1,5 – 2,0","5,6 – 8,0","7,9 – 8,5","6,8 – 7,5"],"r":1,"e":"Le duodénum a un pH 5,6-8,0 grâce à la neutralisation par le suc pancréatique riche en bicarbonates.","s":0},{"q":"Le pH normal du côlon est :","o":["6,8 – 7,5","7,2 – 7,5","7,9 – 8,5","1,5 – 2,0"],"r":2,"e":"Le côlon a un pH 7,9-8,5, le plus basique du tube digestif.","s":0},{"q":"Pendant la phase pharyngée de la déglutition :","o":["Le bol est formé dans la bouche","Le palais mou se soulève pour fermer le nasopharynx","Le sphincter gastro-œsophagien s'ouvre","La progression se fait par péristaltisme"],"r":1,"e":"Phase pharyngée : palais mou ferme le nasopharynx, muscles constricteurs propulsent le bol, sphincter œsophagien supérieur se relâche.","s":0},{"q":"Le foie produit chaque jour :","o":["100 à 200 mL de bile","300 à 500 mL de bile","600 à 1000 mL de bile","1500 à 2000 mL de bile"],"r":2,"e":"Production hépatique : 600 à 1000 mL de bile par jour.","s":0},{"q":"Quelles vitamines sont stockées dans le foie ?","o":["Vitamine A","Vitamine B12","Vitamine C","Vitamine D","Vitamine E","Vitamine K"],"r":[0,1,3,4,5],"e":"Le foie stocke A, B12, D, E, K (liposolubles + B12). La vitamine C n'est pas stockée.","s":0},{"q":"Le rôle de phagocytose du foie élimine :","o":["GR âgés","GB âgés","Bactéries","Débris circulants","Hormones uniquement"],"r":[0,1,2,3],"e":"Cellules de Kupffer phagocytent GR/GB âgés, bactéries, débris circulants.","s":0},{"q":"Le sang traité par le foie repart par :","o":["L'artère hépatique","La veine porte","Les veines hépatiques → veine cave inférieure","Le canal cholédoque"],"r":2,"e":"Sang sortant : veines hépatiques → veine cave inférieure → cœur.","s":0},{"q":"La vésicule biliaire stocke :","o":["20 à 40 mL de bile","40 à 70 mL de bile","100 à 150 mL de bile","200 mL de bile"],"r":1,"e":"Stockage 40-70 mL de bile, concentrée 5 à 10 fois par réabsorption d'eau.","s":0},{"q":"Quelles enzymes digèrent les disaccharides dans l'intestin grêle ?","o":["Pepsine","Maltase","Sucrase","Lactase","Trypsine"],"r":[1,2,3],"e":"Maltase, sucrase, lactase digèrent maltose, saccharose, lactose au niveau de la bordure en brosse.","s":0},{"q":"Les ondes de mélange gastriques durent environ :","o":["5 secondes","20 secondes","1 minute","5 minutes"],"r":1,"e":"Ondes de mélange gastriques ~20 secondes, plus faibles que les ondes péristaltiques.","s":0},{"q":"Les hépatocytes sont :","o":["Les cellules de la vésicule biliaire","Les cellules fonctionnelles du foie","Les cellules pancréatiques","Les cellules de l'intestin"],"r":1,"e":"Hépatocytes = cellules fonctionnelles du foie (production bile, biotransformation, stockage).","s":0},{"q":"Les selles sont composées de :","o":["Uniquement de fibres non digérées","Eau + solides non digérés + micro-organismes + cellules épithéliales","Eau et bactéries uniquement","Catabolites uniquement"],"r":1,"e":"Selles = eau + solides non digérés + micro-organismes + cellules épithéliales desquamées.","s":0},{"q":"La fonction de mélange du système digestif repose sur :","o":["Des contractions segmentaires, à déplacement bidirectionnel des aliments","Le péristaltisme","La déglutition","La mastication"],"r":0,"e":"La propulsion réunit, elle, la déglutition et le péristaltisme.","s":0},{"q":"La fonction de sécrétion du tube digestif fournit :","o":["Du mucus pour la lubrification, de l'eau pour la liquéfaction et des enzymes pour la dégradation","Des hormones seulement","De l'eau seulement","Du mucus seulement"],"r":0,"e":"Elle figure au cinquième rang des huit fonctions du système digestif.","s":0},{"q":"Le pH de la cavité orale se situe entre :","o":["1,5 et 2,0","5,6 et 8,0","6,8 et 7,5","7,9 et 8,5"],"r":2,"e":"L'estomac est à 1,5-2,0, le duodénum à 5,6-8,0, l'intestin grêle à 7,2-7,5 et le côlon à 7,9-8,5.","s":0},{"q":"Le pH de l'intestin grêle se situe entre :","o":["6,8 et 7,5","7,2 et 7,5","7,9 et 8,5","5,6 et 8,0"],"r":1,"e":"Le duodénum présente une fourchette plus large, de 5,6 à 8,0, du fait de la neutralisation progressive de l'acidité gastrique.","s":0},{"q":"Lors de la phase céphalique de la déglutition :","o":["Le bol se forme dans la bouche, la langue le poussant contre le palais dur puis vers l'oropharynx","Le palais mou se soulève","Le sphincter œsophagien supérieur se relâche","Le péristaltisme œsophagien démarre"],"r":0,"e":"La phase pharyngée comporte l'élévation du palais mou, la propulsion par les constricteurs et le relâchement du sphincter supérieur.","s":0},{"q":"Lors de la phase œsophagienne de la déglutition :","o":["Le bol progresse par contractions péristaltiques et le sphincter gastro-œsophagien s'ouvre","Le palais mou se ferme","La langue pousse le bol","Le pylore s'ouvre"],"r":0,"e":"C'est la troisième et dernière phase de la déglutition.","s":0},{"q":"La phase intestinale des sécrétions gastriques est déclenchée par :","o":["Un pH inférieur à 2 et/ou la présence de lipides dans le duodénum, entraînant une inhibition via sécrétine, CCK et GIP","La distension gastrique","Le goût et l'odorat","La gastrine"],"r":0,"e":"La phase gastrique repose sur la distension et les chémorécepteurs, qui libèrent la gastrine.","s":0},{"q":"Lors du remplissage gastrique :","o":["Les plis gastriques s'atténuent et le volume augmente à mesure que les aliments entrent","Les plis s'accentuent","Le volume reste constant","Le pylore s'ouvre"],"r":0,"e":"Le mélange se fait ensuite par des ondes de mélange d'environ 20 secondes et des ondes péristaltiques plus fortes.","s":0},{"q":"Quelle est l'unité fonctionnelle du rein ?","o":["Le glomérule","Le néphron","Le TCP","Le calice"],"r":1,"e":"Le néphron est l'unité fonctionnelle : corpuscule rénal (glomérule + capsule de Bowman) + TCP + anse de Henle + TCD + canal collecteur.","s":1},{"q":"Combien de néphrons compte chaque rein environ ?","o":["~10 000","~100 000","~1 million","~10 millions"],"r":2,"e":"Chaque rein contient environ 1 million de néphrons. Leur nombre ne peut pas augmenter (perte = irréversible).","s":1},{"q":"Quel est le poids approximatif d'un rein ?","o":["~50 g","~140 g","~500 g","~1 kg"],"r":1,"e":"Chaque rein pèse ~140 g. Pourtant, les reins traitent 180 L d'eau et 1,5 kg de sel par jour.","s":1},{"q":"Le cortex rénal est :","o":["La zone interne","La zone externe contenant glomérules et tubules","Le bassinet","L'uretère"],"r":1,"e":"Le cortex (externe) contient les glomérules et la majorité des tubules. La médulla (interne) contient les pyramides de Malpighi.","s":1},{"q":"Quel est le volume d'urine produit par jour environ ?","o":["100 ml","500 ml","1,5 L","5 L"],"r":2,"e":"Volume normal d'urine ≈ 1,5 L/jour. Cela représente seulement ~1% du filtrat (180 L/jour) — le reste est réabsorbé.","s":1},{"q":"L'érythropoïétine est sécrétée par :","o":["Le foie","La rate","Les reins","La moelle osseuse"],"r":2,"e":"Les reins sécrètent l'érythropoïétine (EPO), hormone qui stimule la production de globules rouges dans la moelle osseuse.","s":1},{"q":"Quels sont les 3 étapes de production de l'urine ?","o":["Filtration, réabsorption, sécrétion","Sécrétion, digestion, absorption","Inspiration, expiration, perfusion","Excrétion, défécation, miction"],"r":0,"e":"Les 3 étapes : 1) Filtration glomérulaire, 2) Réabsorption tubulaire, 3) Sécrétion tubulaire.","s":1},{"q":"L'urine est transportée du rein à la vessie par :","o":["L'urètre","Les uretères","Les calices","Le bassinet"],"r":1,"e":"Les uretères (2) transportent l'urine des reins vers la vessie. L'urètre (1) la conduit ensuite hors du corps.","s":1},{"q":"Le détrusor est :","o":["Une enzyme","Le muscle de la vessie","Une partie du néphron","Une hormone"],"r":1,"e":"Le détrusor est le muscle lisse de la paroi vésicale. Sa contraction (parasympathique) permet la miction.","s":1},{"q":"Quel est le débit de filtration glomérulaire (TFG) normal ?","o":["~50 ml/min","~125 ml/min (~180 L/jour)","~300 ml/min","~5 ml/min"],"r":1,"e":"TFG normal ≈ 125 ml/min (~180 L/jour). La clairance de la créatinine est utilisée comme estimation clinique.","s":1},{"q":"Quelles substances NE PASSENT PAS la barrière de filtration glomérulaire ?","o":["Eau et glucose","Ions et urée","Cellules sanguines et protéines plasmatiques","Créatinine"],"r":2,"e":"La barrière retient les cellules sanguines (volumineuses) et les protéines plasmatiques (charge négative + taille). La protéinurie signe une atteinte de cette barrière.","s":1},{"q":"Combien de couches forment la barrière de filtration glomérulaire ?","o":["1 (capillaire)","2","3 (endothélium fenestré + membrane basale + podocytes)","5"],"r":2,"e":"3 couches : 1) endothélium fenestré, 2) membrane basale glomérulaire (charges négatives, repousse les protéines), 3) podocytes (avec leurs pédicelles).","s":1},{"q":"Quel pourcentage du filtrat est réabsorbé au TCP ?","o":["~25%","~50%","~65%","~85%"],"r":2,"e":"Le TCP réabsorbe ~65% du filtrat de manière isosmotique. Réabsorbe la totalité du glucose et des AA, ~50% du Na⁺ et de l'eau.","s":1},{"q":"Quel est le rôle de l'ADH ?","o":["↑ sécrétion de Na⁺","Insère des aquaporines au TCD/canal collecteur → ↑ réabsorption d'eau","Stimule la rénine","Diminue le TFG"],"r":1,"e":"L'ADH (neurohypophyse) augmente la perméabilité du TCD/canal collecteur à l'eau via l'insertion d'aquaporines (AQP2) → urine concentrée.","s":1},{"q":"Dans quelle situation la rénine est-elle libérée ?","o":["Hypertension","Hyperhydratation","Hypotension / baisse du Na⁺","Excès de potassium"],"r":2,"e":"La rénine est libérée par l'appareil juxtaglomérulaire en réponse à : 1) baisse de PA (barorécepteurs), 2) baisse de NaCl (macula densa), 3) stimulation sympathique β1.","s":1},{"q":"L'aldostérone agit principalement en :","o":["↓ réabsorption Na⁺","↑ réabsorption Na⁺/eau et ↑ sécrétion K⁺/H⁺","Stimulant la rénine","Inhibant l'angiotensine II"],"r":1,"e":"L'aldostérone (TCD/canal collecteur) ↑ réabsorption Na⁺ et eau, ↑ sécrétion K⁺ et H⁺. Effecteur final du SRAA.","s":1},{"q":"Que signifie la glycosurie ?","o":["Bonne santé","Diabète non contrôlé (glycémie > seuil rénal ~1,8 g/L)","Déshydratation","Insuffisance rénale"],"r":1,"e":"Glycosurie = glucose dans l'urine. Normalement tout le glucose est réabsorbé au TCP. Si glycémie > seuil rénal (~1,8 g/L), l'excès apparaît dans l'urine. Signe classique de diabète mal équilibré.","s":1},{"q":"Quel est l'effet de l'ANP ?","o":["↑ PA et volémie","Antagonise le SRAA : ↑ TFG, ↓ réabsorption Na⁺, ↓ PA","Active la rénine","Stimule l'aldostérone"],"r":1,"e":"L'ANP (sécrété par les cellules auriculaires en réponse à une distension) antagonise le SRAA : ↑ TFG, ↓ réabsorption Na⁺, inhibe rénine/aldostérone/ADH → ↓ PA.","s":1},{"q":"Quelle est la formule du calcul de la quantité excrétée ?","o":["E = F + R","E = F − R + S","E = F × R / S","E = R − F"],"r":1,"e":"Excrétion (E) = Filtration (F) − Réabsorption (R) + Sécrétion (S). Formule fondamentale de la physiologie rénale.","s":1},{"q":"Le mécanisme à contre-courant fonctionne grâce à :","o":["L'aldostérone seule","L'organisation des anses de Henle et vasa recta en sens opposés (gradient 300 → 1200 mOsm)","La filtration glomérulaire","La vessie"],"r":1,"e":"Le multiplicateur à contre-courant : anses de Henle (descendante perméable à H₂O, ascendante perméable au NaCl) + vasa recta créent un gradient osmotique croissant dans la médulla (300 → 1200 mOsm/kg).","s":1},{"q":"La protéinurie peut signer :","o":["Une bonne hydratation","Une atteinte de la barrière de filtration glomérulaire (néphropathie)","Une infection urinaire uniquement","Une déshydratation"],"r":1,"e":"La protéinurie indique le passage anormal de protéines (souvent albumine) à travers la barrière glomérulaire. Néphropathie diabétique, glomérulonéphrites… (peut être physiologique après un effort intense).","s":1},{"q":"L'urine concentrée est produite quand :","o":["Hyperhydratation","Déshydratation / osmolalité plasmatique ↑ → ↑ ADH","Excès de Na⁺","Insuffisance rénale terminale"],"r":1,"e":"Urine concentrée = ADH élevée. Déclenché par déshydratation (osmolalité ↑) ou volémie ↓ → osmorécepteurs hypothalamiques → ↑ ADH.","s":1},{"q":"L'urine diluée est produite quand :","o":["ADH absente / faible (hyperhydratation)","Déshydratation","Vomissements répétés","Sudation intense"],"r":0,"e":"Sans ADH, le TCD/canal collecteur sont imperméables à l'eau → l'eau reste dans le filtrat → urine diluée et abondante.","s":1},{"q":"Le néphron juxtamédullaire est caractérisé par :","o":["Une anse de Henle courte","Une longue anse de Henle pénétrant profondément la médulla (rôle clé dans la concentration de l'urine)","L'absence de glomérule","Localisation vésicale"],"r":1,"e":"Les néphrons juxtamédullaires (~20%) ont des anses de Henle longues qui plongent dans la médulla. Ils sont essentiels au mécanisme à contre-courant et donc à la concentration de l'urine.","s":1},{"q":"Quel est le calcul de la pression de filtration nette ?","o":["PCG + PHC + POC = 100 mmHg","PCG − PHC − POC = 10 mmHg (55 − 15 − 30)","PCG × PHC / POC","PHC + POC − PCG"],"r":1,"e":"Pression nette = PCG (55) − PHC (15) − POC (30) = 10 mmHg. PCG = pression capillaire glom., PHC = pression hydrostatique capsulaire, POC = pression oncotique.","s":1},{"q":"Quelle est la particularité de la branche descendante de l'anse de Henle ?","o":["Imperméable à l'eau","Très perméable à l'eau, peu aux solutés (filtrat se concentre)","Imperméable à tout","Réabsorbe le glucose"],"r":1,"e":"Branche descendante : très perméable à l'eau, peu aux solutés → l'eau quitte → filtrat se concentre. Ascendante : imperméable à l'eau, perméable au NaCl → filtrat se dilue.","s":1},{"q":"Le segment large de l'anse ascendante utilise :","o":["Une pompe Na⁺/K⁺/2Cl⁻","Une simple diffusion","Aucun transporteur","L'osmose seule"],"r":0,"e":"Le cotransporteur NKCC2 (Na⁺/K⁺/2Cl⁻) du segment large ascendant réabsorbe ~25% du Na⁺ filtré. Cible des diurétiques de l'anse (furosémide).","s":1},{"q":"L'aquaporine 2 (AQP2) est :","o":["Constitutive du TCD","Insérée dans la membrane apicale du canal collecteur sous l'effet de l'ADH","Située dans le glomérule","Dans l'estomac"],"r":1,"e":"L'ADH se fixe sur ses récepteurs V2 → ↑ AMPc → translocation des vésicules contenant AQP2 vers la membrane apicale → réabsorption d'eau. Sans ADH, AQP2 retourne en intracellulaire.","s":1},{"q":"L'angiotensine II augmente la réabsorption de Na⁺ au TCP via :","o":["L'antiporteur Na⁺/H⁺ (NHE3)","Une pompe Cl⁻/HCO₃⁻","L'aquaporine 4","Aucun mécanisme"],"r":0,"e":"L'Ang II stimule l'antiporteur Na⁺/H⁺ (NHE3) au TCP, augmentant la réabsorption de Na⁺ (et donc d'eau). Action directe sur le tubule, en plus de la stimulation de l'aldostérone.","s":1},{"q":"Le mécanisme tubuloglomérulaire est :","o":["Sans rétroaction","Une rétroaction de la macula densa qui ajuste le TFG selon le NaCl tubulaire","Une action de l'ADH","Une activité de l'aldostérone"],"r":1,"e":"Rétroaction tubulo-glomérulaire : la macula densa (TCD) détecte le NaCl. Si NaCl ↑ (TFG trop élevé), libération d'adénosine → vasoconstriction de l'artériole afférente → ↓ TFG.","s":1},{"q":"Le taux de filtration glomérulaire (TFG) normal est :","o":["~25 mL/min","~125 mL/min = ~180 L/jour","~500 mL/min","~1,5 L/min"],"r":1,"e":"TFG = 125 mL/min = 180 L/jour de filtrat, dont seulement 1% est excrété comme urine.","s":1},{"q":"La pression de filtration nette se calcule :","o":["PCG + PHC + POC","PCG − PHC − POC","PHC − PCG − POC","POC − PCG + PHC"],"r":1,"e":"Pression nette = PCG (~55) − PHC (~15) − POC (~30) = 10 mmHg.","s":1},{"q":"Que passe à travers la membrane de filtration glomérulaire ?","o":["Eau","Petits ions","Glucose","Urée","Cellules sanguines","Albumine"],"r":[0,1,2,3],"e":"Passent : eau, petits solutés (ions, glucose, urée, créatinine, AA). Ne passent PAS : cellules sanguines et protéines plasmatiques.","s":1},{"q":"Le tubule contourné proximal (TCP) réabsorbe :","o":["~10% du filtrat","~30% du filtrat","~65% du filtrat","~95% du filtrat"],"r":2,"e":"TCP réabsorbe ~65% du filtrat, 50% Na+/eau, glucose totalité, AA, HCO3-, par bordure en brosse.","s":1},{"q":"L'anse de Henle descendante est :","o":["Très perméable à l'eau, peu aux solutés","Imperméable à l'eau, perméable au NaCl","Perméable au glucose","Sécrète l'ADH"],"r":0,"e":"Branche descendante : très perméable à l'eau (sort par osmose), peu aux solutés → filtrat se concentre.","s":1},{"q":"L'anse de Henle ascendante est caractérisée par :","o":["Imperméable à l'eau, réabsorbe NaCl via pompe Na+/K+/2Cl-","Très perméable à l'eau","Sécrète des H+","Réabsorbe le glucose"],"r":0,"e":"Branche ascendante : imperméable à l'eau, pompe Na+/K+/2Cl- réabsorbe ~15% du filtrat → filtrat se dilue.","s":1},{"q":"L'ADH (vasopressine) agit en :","o":["Augmentant la sécrétion d'aldostérone","Insérant des aquaporines dans le TCD et canal collecteur","Bloquant la filtration glomérulaire","Stimulant la pompe Na/K"],"r":1,"e":"ADH insère des aquaporines dans les membranes du TCD/canal collecteur → eau quitte le filtrat → urine concentrée.","s":1},{"q":"Les néphrons juxtamédullaires :","o":["Représentent ~80% des néphrons","Ont des anses courtes","Représentent ~20% et ont des anses longues clés pour la concentration urinaire","Sont uniquement dans le cortex"],"r":2,"e":"Juxtamédullaires (~20%) ont anses longues qui pénètrent dans la médulla, essentiels pour le mécanisme à contre-courant.","s":1},{"q":"Le réflexe de miction est déclenché par :","o":["La contraction volontaire du sphincter externe","La distension de la vessie, qui active un arc réflexe parasympathique (S2-S4)","La libération d'ADH par la post-hypophyse","La chute du débit de filtration glomérulaire"],"r":1,"e":"Vers 200-300 mL, les mécanorécepteurs de la paroi vésicale sont étirés ; l'influx gagne la moelle sacrée S2-S4, d'où part la commande parasympathique qui contracte le détrusor et relâche le sphincter interne. Le sphincter externe, strié, reste sous contrôle volontaire.","s":1},{"q":"Le trigone vésical est délimité par :","o":["Les deux orifices urétéraux et l'orifice urétral interne","Les deux sphincters de l'urètre","Le col vésical et le pelvis rénal","Les deux artères vésicales"],"r":0,"e":"Le trigone est le triangle lisse du plancher vésical dont les trois sommets sont les deux abouchements des uretères et l'orifice interne de l'urètre. Sa muqueuse, peu plissée, est une zone de départ fréquente des infections et des tumeurs.","s":1},{"q":"Le sphincter externe de l'urètre est :","o":["Lisse, involontaire","Strié, volontaire","Cardiaque","Absent"],"r":1,"e":"Sphincter externe = strié, volontaire (contrôle conscient). Sphincter interne = lisse, involontaire.","s":1},{"q":"Les déchets éliminés par sécrétion tubulaire incluent :","o":["H+","K+","Glucose","NH4+","Créatinine","Médicaments"],"r":[0,1,3,4,5],"e":"Sécrétion : H+, K+, NH4+, urée, créatinine, médicaments. Le glucose est totalement réabsorbé, pas sécrété.","s":1},{"q":"Chaque jour, les reins traitent environ :","o":["180 L d'eau et 1,5 kg de sel, pour un poids de 140 g chacun","18 L d'eau","1,5 L d'eau","500 L d'eau"],"r":0,"e":"Ce contraste entre le volume traité et la masse de l'organe illustre son efficacité.","s":1},{"q":"La régulation du pH par le rein passe par :","o":["La sécrétion de quantités variables d'ions H⁺ dans le liquide extracellulaire","La sécrétion de bicarbonates seule","La filtration des protéines","L'érythropoïétine"],"r":0,"e":"Les six fonctions du système urinaire comprennent aussi filtration, régulation du volume et des solutés, synthèse des globules rouges et vitamine D.","s":1},{"q":"La régulation de la synthèse de vitamine D par le rein permet :","o":["Le contrôle des taux de calcium dans le sang","La régulation du sodium","La synthèse des globules rouges","La régulation du pH"],"r":0,"e":"L'érythropoïétine régule, elle, la synthèse des globules rouges dans la moelle osseuse.","s":1},{"q":"La vascularisation rénale suit l'ordre :","o":["Artère rénale, segmentaires, interlobaires, arquées, interlobulaires, artériole afférente, glomérule, artériole efférente, capillaires péritubulaires","Artère rénale, glomérule, artériole afférente","Artériole efférente, glomérule, artériole afférente","Artère rénale, arquées, segmentaires"],"r":0,"e":"Les vasa recta accompagnent les néphrons juxtamédullaires.","s":1},{"q":"Les néphrons corticaux représentent environ :","o":["20 % des néphrons","50 %","80 %","95 %"],"r":2,"e":"Les néphrons juxtamédullaires, environ 20 %, ont de très longues anses et jouent le rôle clé dans la concentration de l'urine.","s":1},{"q":"Le débit de filtration glomérulaire est d'environ :","o":["125 mL/min, soit 180 L/jour","25 mL/min","250 mL/min","60 mL/min"],"r":0,"e":"Plus de 99 % du filtrat retourne dans le sang, seul 1 % étant excrété, soit environ 1,5 L par jour.","s":1},{"q":"La pression capillaire glomérulaire est d'environ :","o":["55 mmHg, et force la filtration","15 mmHg","30 mmHg","10 mmHg"],"r":0,"e":"La pression hydrostatique capsulaire (15 mmHg) et la pression oncotique (30 mmHg) s'y opposent, donnant une filtration nette de 10 mmHg.","s":1},{"q":"Le tubule contourné proximal réabsorbe environ :","o":["65 % du filtrat, dont 50 % du sodium et de l'eau, et la totalité du glucose","15 % du filtrat","90 %","30 %"],"r":0,"e":"Il est perméable à l'eau, donc isosmotique, et possède une bordure en brosse.","s":1},{"q":"Quel est le pH normal du sang artériel ?","o":["7,00 – 7,15","7,35 – 7,45","7,55 – 7,65","7,80 – 8,00"],"r":1,"e":"pH artériel normal = 7,35–7,45 (≈ 7,40). En dessous = acidémie ; au-dessus = alcalémie.","s":2},{"q":"Le pH se calcule par :","o":["log [OH⁻]","−log [H⁺]","[H⁺] × 10","[H⁺]/[OH⁻]"],"r":1,"e":"pH = −log [H⁺]. Une variation de 1 unité pH = variation × 10 de [H⁺].","s":2},{"q":"Une acidose correspond à :","o":["pH > 7,45","pH < 7,35","pH = 7,40","pH = 7,00"],"r":1,"e":"Acidose = pH < 7,35. Alcalose = pH > 7,45. Variation de 1 pH = ×10 [H⁺].","s":2},{"q":"Quels sont les 6 électrolytes clés ?","o":["Na⁺, K⁺, Cl⁻, HCO₃⁻, Ca²⁺, PO₄³⁻","C, H, N, O, P, S","Fe, Cu, Zn, Mg, Mn, Se","Vit A, B, C, D, E, K"],"r":0,"e":"Les 6 électrolytes principaux : sodium, potassium, chlorure, bicarbonate, calcium, phosphate.","s":2},{"q":"Le fluide intracellulaire représente environ :","o":["20% de l'eau totale","60% de l'eau totale (~25 L)","100%","5%"],"r":1,"e":"Le LIC ≈ 60% de l'eau corporelle totale (~25 L chez l'adulte). Le LEC = 1/3 (plasma 20% + interstitiel 80%).","s":2},{"q":"L'apport hydrique quotidien est environ :","o":["500 ml","1 000 ml","2 500 ml","10 000 ml"],"r":2,"e":"Apport hydrique ≈ 2 500 ml/j : boissons (1 600) + aliments (700) + eau métabolique (200).","s":2},{"q":"Le pH cytoplasmique cellulaire est :","o":["7,40 (= sang)","≈ 6,8 (légèrement plus acide que le sang)","8,5","5,0"],"r":1,"e":"Le pH intracellulaire (~6,8) est légèrement plus acide que le pH sanguin (~7,40). Production constante de CO₂ et acides métaboliques.","s":2},{"q":"Un acide est une substance qui :","o":["Capte les H⁺","Libère des H⁺ en solution","Libère des OH⁻","Ne fait rien"],"r":1,"e":"Acide (Brønsted) = donneur de H⁺. Base = accepteur de H⁺. HCl → H⁺ + Cl⁻.","s":2},{"q":"Le HCl est un :","o":["Acide faible","Acide fort (entièrement dissocié)","Base forte","Tampon"],"r":1,"e":"HCl est un acide fort entièrement dissocié en H⁺ + Cl⁻. C'est l'acide gastrique.","s":2},{"q":"Une acidose métabolique est caractérisée par :","o":["pH > 7,45 et HCO₃⁻ ↑","pH < 7,35 et HCO₃⁻ ↓ (<22 mEq/L)","pH < 7,35 et pCO₂ ↑","pH > 7,45 et pCO₂ ↓"],"r":1,"e":"Acidose métabolique = pH < 7,35 et HCO₃⁻ ↓. Causes : acidose lactique, cétoacidose diabétique, insuffisance rénale, diarrhée.","s":2},{"q":"Une acidose respiratoire est caractérisée par :","o":["pH < 7,35 et pCO₂ ↑ (>45 mmHg)","pH > 7,45 et pCO₂ ↓","pH < 7,35 et HCO₃⁻ ↓","pH normal"],"r":0,"e":"Acidose respiratoire = pH < 7,35 et pCO₂ > 45 mmHg. Causes : hypoventilation (BPCO, emphysème, dépression respiratoire).","s":2},{"q":"Une alcalose respiratoire est caractérisée par :","o":["pH < 7,35 et pCO₂ ↑","pH > 7,45 et pCO₂ ↓ (<35 mmHg)","pH > 7,45 et HCO₃⁻ ↑","Aucun de ces"],"r":1,"e":"Alcalose respiratoire = hyperventilation → pCO₂ ↓ < 35 mmHg → pH > 7,45. Causes : anxiété, altitude, AVC.","s":2},{"q":"Une alcalose métabolique est caractérisée par :","o":["pH > 7,45 et HCO₃⁻ ↑","pH > 7,45 et pCO₂ ↓","pH < 7,35 et HCO₃⁻ ↓","Aucun"],"r":0,"e":"Alcalose métabolique = pH > 7,45 et HCO₃⁻ ↑. Causes : vomissements répétés (perte d'HCl), ingestion d'alcalins, hypokaliémie.","s":2},{"q":"Quelle situation provoque une alcalose respiratoire ?","o":["Hypoventilation","Hyperventilation (anxiété, altitude)","Vomissements répétés","Diarrhée sévère"],"r":1,"e":"L'hyperventilation élimine trop de CO₂ → pCO₂ ↓ → pH ↑. Causes typiques : crise d'angoisse, altitude, AVC.","s":2},{"q":"Quel est le tampon principal du plasma ?","o":["Tampon protéique","Tampon hémoglobine","Tampon bicarbonate (HCO₃⁻/H₂CO₃)","Tampon phosphate"],"r":2,"e":"Le couple HCO₃⁻/H₂CO₃ est le tampon principal extracellulaire (plasma + liquide interstitiel). Régulé par poumons (CO₂) et reins (HCO₃⁻).","s":2},{"q":"Le tampon le plus abondant (3/4 de la capacité tampon totale) est :","o":["Bicarbonate","Phosphate","Protéique (intra et extracellulaire, dont l'hémoglobine)","Ammoniac"],"r":2,"e":"Les protéines (groupements –COOH/–NH₂ ionisables) représentent ~75% de la capacité tampon totale, en intra et extracellulaire.","s":2},{"q":"Le tampon bicarbonate en cas d'acidose réagit ainsi :","o":["HCO₃⁻ + H⁺ → H₂CO₃ → CO₂ + H₂O (CO₂ éliminé par les poumons)","H₂CO₃ → H⁺ + HCO₃⁻","Na⁺ + Cl⁻ → NaCl","OH⁻ → H₂O"],"r":0,"e":"En acidose, HCO₃⁻ capte H⁺ → H₂CO₃ → CO₂ + H₂O. Le CO₂ est éliminé par les poumons (réponse rapide).","s":2},{"q":"Quel est le rôle du tampon hémoglobine ?","o":["Tampon plasmatique principal","Tampon intracellulaire des érythrocytes (capte H⁺ libéré par CO₂)","Tampon dans le foie","Tampon urinaire"],"r":1,"e":"Hb capte H⁺ libéré par la dissociation H₂CO₃ → H⁺ + HCO₃⁻. ~70-80% du CO₂ tissulaire est transporté sous forme HCO₃⁻ via l'anhydrase carbonique érythrocytaire.","s":2},{"q":"Le tampon ammoniac (NH₃/NH₄⁺) agit principalement :","o":["Dans le plasma","Dans les érythrocytes","Dans les tubules rénaux distaux","Dans le foie"],"r":2,"e":"NH₃ + H⁺ → NH₄⁺ excrété dans l'urine. Permet d'éliminer H⁺ tout en préservant le HCO₃⁻ plasmatique.","s":2},{"q":"Le tampon phosphate agit principalement :","o":["Dans le plasma uniquement","Dans le cytoplasme cellulaire et les tubules rénaux","Dans les voies digestives","Dans la bile"],"r":1,"e":"Le tampon phosphate (HPO₄²⁻/H₂PO₄⁻) est principalement intracellulaire et tubulaire rénal. Concentration trop faible dans le LEC pour y être important.","s":2},{"q":"Pendant un effort intense (anaérobie), l'acide produit est :","o":["Acide carbonique","Acide lactique","Acide phosphorique","Acide sulfurique"],"r":1,"e":"Glycolyse anaérobie : glucose → pyruvate → lactate (acide lactique). Source de H⁺ qui doit être tamponnée.","s":2},{"q":"Le métabolisme aérobie produit comme acide :","o":["Acide lactique","Acide carbonique (CO₂ + H₂O → H₂CO₃)","Acide sulfurique","Acide phosphorique"],"r":1,"e":"Le CO₂ produit par le métabolisme aérobie + H₂O → H₂CO₃ → H⁺ + HCO₃⁻. C'est la source principale (normale) de H⁺.","s":2},{"q":"L'oxydation des AA soufrés (méthionine, cystéine) produit :","o":["Acide acétique","Acide sulfurique (H₂SO₄)","Acide lactique","CO₂"],"r":1,"e":"L'oxydation des AA soufrés produit H₂SO₄, acide non volatil qui doit être éliminé par les reins (sous forme de SO₄²⁻ urinaire).","s":2},{"q":"Une respiration de Kussmaul est typique de :","o":["Alcalose métabolique","Alcalose respiratoire","Acidose métabolique sévère","Acidose respiratoire"],"r":2,"e":"Respiration de Kussmaul = hyperventilation rapide et profonde, compensation respiratoire d'une acidose métabolique sévère (ex : acidocétose diabétique).","s":2},{"q":"L'équation de Henderson-Hasselbalch pour le système bicarbonate est :","o":["pH = pKa + log ([HCO₃⁻] / [H₂CO₃])","pH = [H⁺] × [OH⁻]","pH = log([H⁺] / [OH⁻])","pH = HCO₃⁻ × CO₂"],"r":0,"e":"Henderson-Hasselbalch : pH = pKa + log([HCO₃⁻]/[H₂CO₃]). pKa = 6,1. [HCO₃⁻] / [CO₂ × 0,03] doit ≈ 20 pour pH = 7,40.","s":2},{"q":"Le rapport HCO₃⁻ / H₂CO₃ normal est :","o":["1/1","20/1 (pour pH = 7,40)","100/1","1/20"],"r":1,"e":"Pour un pH = 7,40, [HCO₃⁻]/[H₂CO₃] = 20/1 (24 mmol/L / 1,2 mmol/L). Tout déséquilibre de ce ratio entraîne acidose/alcalose.","s":2},{"q":"L'anhydrase carbonique catalyse :","o":["HCl → H⁺ + Cl⁻","CO₂ + H₂O ⇌ H₂CO₃ ⇌ H⁺ + HCO₃⁻","Na⁺ + Cl⁻ → NaCl","Hb + O₂ → HbO₂"],"r":1,"e":"Anhydrase carbonique catalyse l'hydratation rapide du CO₂ en H₂CO₃ (et réaction inverse). Présente dans érythrocytes, cellules tubulaires rénales, estomac. Cible des inhibiteurs (acétazolamide).","s":2},{"q":"Le trou anionique (anion gap) est calculé par :","o":["[Na⁺] − ([Cl⁻] + [HCO₃⁻]) (normal ~12)","[K⁺] + [Cl⁻]","[HCO₃⁻] − [pCO₂]","pH × pCO₂"],"r":0,"e":"Anion gap = [Na⁺] − ([Cl⁻] + [HCO₃⁻]) ≈ 8–12 mEq/L. Augmenté dans acidoses métaboliques avec accumulation d'acides organiques (lactate, cétones, salicylates).","s":2},{"q":"Une acidose métabolique avec anion gap élevé suggère :","o":["Diarrhée","Acidocétose, acidose lactique, intoxication (méthanol, éthylène glycol)","Vomissements","Hyperventilation"],"r":1,"e":"Anion gap élevé → accumulation d'acides organiques non-mesurés : MUDPILES (Méthanol, Urémie, Diabétique cétoacidose, Propylène/Paraldéhyde, Iron/Isoniazide, Lactate, Éthylène glycol, Salicylates).","s":2},{"q":"Une compensation respiratoire d'acidose métabolique se traduit par :","o":["↑ ventilation → ↓ pCO₂ (Kussmaul)","↓ ventilation → ↑ pCO₂","↑ HCO₃⁻ rénal seul","Aucune compensation"],"r":0,"e":"Acidose métabolique → chémorécepteurs périphériques détectent ↓ pH → ↑ ventilation → pCO₂ ↓ → ramène le pH vers la normale (compensation rapide, partielle).","s":2},{"q":"Le fluide intracellulaire (ICF) représente :","o":["~10% de l'eau totale","~30% de l'eau totale","~60% de l'eau totale (~25 L)","~90% de l'eau totale"],"r":2,"e":"ICF ≈ 60% eau totale (~25L) ; ECF ≈ 1/3 (plasma + interstitiel).","s":2},{"q":"L'apport hydrique quotidien moyen est :","o":["~500 mL/j","~1500 mL/j","~2500 mL/j","~5000 mL/j"],"r":2,"e":"Apport ~2500 mL/j (boissons 1600 + aliments 700 + eau métabolique 200).","s":2},{"q":"pH < 6,85 ou pH > 7,95 entraîne :","o":["Une légère somnolence","Aucun effet","La mort cellulaire","Une accélération métabolique"],"r":2,"e":"Au-delà de ces bornes, mort cellulaire car les protéines/canaux perdent leur structure 3D.","s":2},{"q":"Une variation de 1 unité de pH correspond à :","o":["×2 [H+]","×5 [H+]","×10 [H+]","×100 [H+]"],"r":2,"e":"Échelle logarithmique : 1 unité pH = facteur 10 sur [H+].","s":2},{"q":"Les sources de H+ issues du métabolisme incluent :","o":["Métabolisme aérobie (CO2 → H2CO3)","Métabolisme anaérobie (acide lactique)","Oxydation des AG (corps cétoniques)","Oxydation des AA soufrés (acide sulfurique)","Hydrolyse phosphoprotéines (acide phosphorique)","L'excrétion rénale des H⁺ dans l'urine"],"r":[0,1,2,3,4],"e":"Toutes ces voies génèrent des H+. Source principale en conditions normales : CO2 de la respiration aérobie. L'excrétion rénale élimine les H⁺, elle n'en produit pas : c'est un mécanisme de compensation, pas une source.","s":2},{"q":"Les mécanismes tampons de l'organisme sont principalement :","o":["Anti-alcalosiques","Anti-acidosiques","Pro-acidosiques","Neutres"],"r":1,"e":"L'organisme produit beaucoup plus d'acides → mécanismes tampons principalement anti-acidosiques.","s":2},{"q":"Le tampon le plus abondant (3/4 de la capacité tampon) est :","o":["Le bicarbonate","L'hémoglobine","Le tampon protéique","Le phosphate"],"r":2,"e":"Tampon protéique = 3/4 de la capacité tampon totale (intracellulaire et plasmatique).","s":2},{"q":"Comparée aux tampons chimiques, la compensation RÉNALE d'un déséquilibre acido-basique est :","o":["Immédiate mais très limitée en capacité","Lente (heures à jours) mais la plus puissante et la seule à éliminer réellement les H⁺","Impossible en cas d'acidose métabolique","Strictement identique à la compensation respiratoire"],"r":1,"e":"Trois lignes de défense se succèdent : les tampons chimiques (secondes, capacité limitée), la compensation respiratoire (minutes), puis le rein (heures à jours). Seul le rein excrète définitivement les H⁺ fixes et régénère le HCO₃⁻ ; c'est donc le mécanisme le plus lent mais le plus puissant.","s":2},{"q":"Quel pourcentage du CO2 tissulaire est transporté en HCO3- ?","o":["10–20%","30–40%","50–60%","70–80%"],"r":3,"e":"70-80% du CO2 transporté sous forme HCO3- dans le plasma, via l'anhydrase carbonique.","s":2},{"q":"L'acidose métabolique est caractérisée par :","o":["pCO2 > 45 mmHg","HCO3- < 22 mEq/L et pH < 7,35","HCO3- > 26 mEq/L","pH > 7,45"],"r":1,"e":"Acidose métabolique : ↓ HCO3- (<22 mEq/L) et pH < 7,35. Causes : acidose lactique, cétoacidose, IR, diarrhée.","s":2},{"q":"La respiration de Kussmaul (rapide et profonde) est associée à :","o":["L'alcalose respiratoire","L'acidose métabolique","L'alcalose métabolique","L'acidose respiratoire"],"r":1,"e":"Respiration de Kussmaul = compensation de l'acidose métabolique : ↑ fréquence et amplitude pour expulser le CO2.","s":2},{"q":"La tétanie en cas d'alcalose s'explique par :","o":["Une hyperkaliémie","Une hypocalcémie (Ca2+ se dépose dans la matrice osseuse)","Une hypoglycémie","Une hyperthermie"],"r":1,"e":"Alcalose → dépôt de Ca2+ dans les os → hypocalcémie → canaux Na+ non bloqués → hyper-excitabilité → tétanie.","s":2},{"q":"Le fluide extracellulaire se compose :","o":["Du plasma, pour 20 %, et du fluide interstitiel","Du seul plasma","Du seul liquide interstitiel","Du liquide intracellulaire"],"r":0,"e":"Il représente environ un tiers de l'eau totale, contre 60 % pour le fluide intracellulaire, soit environ 25 L.","s":2},{"q":"L'apport hydrique quotidien de 2 500 mL se répartit en :","o":["1 600 mL de boissons, 700 mL d'aliments et 200 mL d'eau métabolique","2 500 mL de boissons","1 000 mL de boissons et 1 500 d'aliments","500 mL de boissons"],"r":0,"e":"Les pertes se répartissent en 1 500 mL d'urine, 400 par la peau, 300 par l'air expiré, 100 par les selles et 100 par la sueur.","s":2},{"q":"La régulation du sodium et du potassium repose sur :","o":["L'aldostérone, qui augmente la réabsorption de sodium et l'excrétion de potassium, et l'angiotensine II","L'ADH seule","Le pH","Le calcium"],"r":0,"e":"Les six électrolytes clés sont Na⁺, K⁺, Cl⁻, HCO₃⁻, Ca²⁺ et PO₄³⁻.","s":2},{"q":"Une acidose entraîne :","o":["Une dépression du système nerveux central","Une hyper-excitabilité","Une tétanie","Des convulsions"],"r":0,"e":"L'alcalose, au-dessus de 7,45, provoque au contraire une hyper-excitabilité du SNC.","s":2},{"q":"L'hydrolyse des phosphoprotéines produit :","o":["De l'acide phosphorique","De l'acide sulfurique","De l'acide lactique","Des corps cétoniques"],"r":0,"e":"L'oxydation des acides aminés soufrés produit de l'acide sulfurique et celle des acides gras des corps cétoniques.","s":2},{"q":"L'acidose respiratoire se caractérise par :","o":["Une pCO₂ supérieure à 45 mmHg, par hypoventilation, emphysème, œdème pulmonaire ou obstruction","Un HCO₃⁻ inférieur à 22 mEq/L","Une pCO₂ inférieure à 35 mmHg","Un HCO₃⁻ élevé"],"r":0,"e":"Elle entraîne une dépression du SNC, voire un coma, avec une respiration déprimée.","s":2},{"q":"L'acidose métabolique se caractérise par :","o":["Un HCO₃⁻ inférieur à 22 mEq/L, par acide lactique, corps cétoniques, insuffisance rénale ou diarrhée sévère","Une pCO₂ élevée","Une pCO₂ basse","Un HCO₃⁻ élevé"],"r":0,"e":"Elle provoque une respiration de Kussmaul, rapide et profonde, et des problèmes cardiovasculaires.","s":2},{"q":"L'alcalose respiratoire se manifeste par :","o":["Picotements, tremblements, confusion et crise épileptique possible","Une dépression du SNC","Une respiration de Kussmaul","Un coma"],"r":0,"e":"Elle résulte d'une hyperventilation, par anxiété sévère, altitude ou AVC, avec une pCO₂ inférieure à 35 mmHg.","s":2},{"q":"Combien de chromosomes contient une cellule somatique humaine ?","o":["23 (haploïde)","46 (diploïde, 23 paires)","92","44 sans chromosomes sexuels"],"r":1,"e":"Cellule somatique = 2n = 46 chromosomes (22 paires d'autosomes + 1 paire sexuelle XX/XY). Gamètes haploïdes n=23.","s":3},{"q":"Combien de chromosomes contient un gamète humain ?","o":["23 (haploïde)","46","92","44"],"r":0,"e":"Les gamètes (spermatozoïde, ovule) sont haploïdes : n = 23 chromosomes (issus de la méiose).","s":3},{"q":"Le caryotype féminin est :","o":["46, XY","46, XX","47, XXY","45, X"],"r":1,"e":"Caryotype féminin normal = 46, XX. Caryotype masculin = 46, XY. Anomalies : Klinefelter (47, XXY), Turner (45, X).","s":3},{"q":"Combien de jours dure le cycle menstruel typique ?","o":["~14 jours","~21 jours","~28 jours","~35 jours"],"r":2,"e":"Cycle menstruel typique : ~28 jours (variable de 21 à 35 jours).","s":3},{"q":"Quand a lieu l'ovulation lors d'un cycle de 28 jours ?","o":["Jour 7","Jour 14 (après le pic de LH)","Jour 21","Jour 1"],"r":1,"e":"Ovulation ~24h après le pic de LH, généralement vers le jour 14 du cycle.","s":3},{"q":"Où a lieu la spermatogenèse ?","o":["Cellules de Leydig","Tubes séminifères des testicules","Épididyme","Prostate"],"r":1,"e":"Spermatogenèse = tubes séminifères des testicules. Maturation finale dans l'épididyme.","s":3},{"q":"Quelles cellules produisent la testostérone ?","o":["Cellules de Sertoli","Cellules de Leydig (interstitielles, sous LH)","Cellules de Kupffer","Cellules béta"],"r":1,"e":"Cellules de Leydig = cellules interstitielles testiculaires, sous contrôle de la LH, produisent la testostérone.","s":3},{"q":"Quel est le rôle des cellules de Sertoli ?","o":["Produire la testostérone","Soutenir la spermatogenèse, sécréter l'inhibine, sous FSH","Fabriquer le sperme","Sécréter le mucus"],"r":1,"e":"Cellules de Sertoli (sous FSH) : nourrissent et soutiennent les cellules germinales, sécrètent l'inhibine (rétroaction négative sur FSH).","s":3},{"q":"L'âge moyen de la puberté chez la fille est :","o":["6–8 ans","11–13 ans","16–18 ans","20–22 ans"],"r":1,"e":"Puberté féminine : 11–13 ans (↑ œstrogènes + progestérone). Ménarche entre 11 et 16 ans typiquement.","s":3},{"q":"Quel est le rôle de la FSH chez l'homme ?","o":["Stimuler la testostérone","Stimuler la spermatogenèse via les cellules de Sertoli","Inhiber la GnRH","Réguler l'érection"],"r":1,"e":"FSH ♂ : agit sur les cellules de Sertoli → spermatogenèse. LH ♂ : agit sur cellules de Leydig → testostérone.","s":3},{"q":"L'hormone produite par le corps jaune après l'ovulation est :","o":["Œstrogènes seuls","Progestérone (et un peu d'œstrogènes)","FSH/LH","Inhibine seule"],"r":1,"e":"Corps jaune (corpus luteum) sécrète principalement de la progestérone (et œstrogènes) pour préparer l'endomètre à une éventuelle nidation.","s":3},{"q":"Si la fécondation n'a pas lieu, que devient le corps jaune ?","o":["Continue à produire de la progestérone","Dégénère (corpus albicans) → ↓ progestérone → menstruation","Devient un nouveau follicule","Libère un autre ovocyte"],"r":1,"e":"Sans fécondation, le corps jaune dégénère vers J24-26 → corpus albicans → ↓ progestérone et œstrogènes → desquamation endométriale = règles.","s":3},{"q":"Où se déroule la fécondation ?","o":["Utérus","Ovaire","Ampoule de la trompe de Fallope (1/3 externe)","Vagin"],"r":2,"e":"Fécondation dans l'ampoule de la trompe de Fallope. L'œuf migre ensuite vers l'utérus où il s'implante (~J6-7).","s":3},{"q":"Quelle est la durée de vie d'un spermatozoïde dans les voies féminines ?","o":["1 heure","12 heures","3 à 5 jours","1 mois"],"r":2,"e":"Spermatozoïde survit 3–5 jours dans les voies féminines. Ovocyte fécondable ~24h. Fenêtre de fertilité : ~6 jours autour de l'ovulation.","s":3},{"q":"L'hCG est sécrétée par :","o":["L'hypophyse","Le trophoblaste embryonnaire dès l'implantation","L'ovaire","L'hypothalamus"],"r":1,"e":"hCG = gonadotrophine chorionique humaine, sécrétée par le trophoblaste/placenta dès l'implantation. Maintient le corps jaune jusqu'à ~10-12 SA. Détectée par les tests de grossesse.","s":3},{"q":"Quel est le rôle principal de la testostérone ?","o":["Régule la glycémie","Caractères sexuels masculins, spermatogenèse, libido, masse musculaire, érythropoïèse","Production de bile","Croissance osseuse uniquement"],"r":1,"e":"Testostérone : caractères sexuels secondaires masculins, soutient la spermatogenèse, libido, masse musculaire (anabolisant), érythropoïèse, voix grave, pilosité, métabolisme.","s":3},{"q":"Le pic de LH déclenche :","o":["La menstruation","L'ovulation (rupture du follicule de De Graaf)","La fécondation","La nidation"],"r":1,"e":"Pic de LH (déclenché par rétroaction positive des œstrogènes) → rupture du follicule de De Graaf → ovulation (~24h après le pic).","s":3},{"q":"Quel est le pic d'hormone qui déclenche le pic de LH ?","o":["Progestérone","Œstrogènes (rétroaction positive en fin de phase folliculaire)","Inhibine","FSH"],"r":1,"e":"En fin de phase folliculaire, les œstrogènes deviennent très élevés → bascule de rétroaction négative vers positive → pic de GnRH → pic de LH (et FSH).","s":3},{"q":"La phase folliculaire dure :","o":["Toujours 14 jours fixes","Variable (6–16 jours selon la longueur du cycle)","Toujours 21 jours","1 mois"],"r":1,"e":"Phase folliculaire = variable. C'est elle qui détermine la longueur du cycle. Phase lutéale = constante 14 jours.","s":3},{"q":"La phase lutéale dure :","o":["Variable","Constante = 14 jours","21 jours","7 jours"],"r":1,"e":"Phase lutéale = TOUJOURS 14 jours (durée de vie du corps jaune en l'absence de grossesse). C'est la phase folliculaire qui varie.","s":3},{"q":"L'inhibine est sécrétée par :","o":["Hypothalamus","Cellules de Sertoli (♂) / cellules de la granulosa (♀)","Cellules de Leydig","Hypophyse"],"r":1,"e":"Inhibine : ♂ Sertoli, ♀ granulosa → rétroaction négative spécifique sur la FSH (sans agir sur la LH).","s":3},{"q":"Le follicule de De Graaf correspond au :","o":["Follicule primordial","Follicule mature/tertiaire prêt à ovuler","Corps jaune","Corps albicans"],"r":1,"e":"Follicule de De Graaf = follicule mature (tertiaire/antral), volumineux, prêt à se rompre lors de l'ovulation.","s":3},{"q":"L'ovogenèse commence :","o":["À la puberté","Avant la naissance (méiose I bloquée en prophase I)","Après la ménopause","À 20 ans"],"r":1,"e":"L'ovogenèse débute pendant la vie fœtale, méiose I bloquée en prophase I jusqu'à la puberté. Stock fixe d'ovocytes à la naissance (~400 000).","s":3},{"q":"Quand la méiose II est-elle complétée chez la femme ?","o":["Avant la naissance","À la puberté","Au moment du pic de LH","Après la pénétration du spermatozoïde (fécondation)"],"r":3,"e":"Méiose II est bloquée en métaphase II et n'est complétée qu'APRÈS la pénétration du spermatozoïde dans l'ovocyte II.","s":3},{"q":"Le clivage de l'angiotensinogène par la rénine produit :","o":["Aldostérone","Angiotensine I (qui sera ensuite convertie en Ang II par l'ECA)","Hormone hypothalamique","Calcitonine"],"r":1,"e":"Note : ce concept appartient au Cours 2. Pour le système reproducteur, retenir que les axes hormonaux sont précisément régulés par cascades enzymatiques similaires.","s":3},{"q":"Le 1er corps polaire est libéré :","o":["Avant la naissance","Au moment du pic de LH (achèvement méiose I, juste avant ovulation)","Après la fécondation","Pendant la nidation"],"r":1,"e":"Pic de LH → achèvement de la méiose I → libération du 1er globule polaire et formation de l'ovocyte II. Méiose II reprendra qu'à la fécondation.","s":3},{"q":"L'implantation a lieu vers :","o":["Le jour de la fécondation","Jour 6-7 post-fécondation (blastocyste)","Jour 14","Jour 28"],"r":1,"e":"Après fécondation, l'œuf se divise en cheminant dans la trompe → blastocyste → implantation dans l'endomètre vers J6-7 post-fécondation.","s":3},{"q":"Le placenta prend le relais du corps jaune vers :","o":["1 SA","10–12 SA","20 SA","À l'accouchement"],"r":1,"e":"L'hCG maintient le corps jaune jusqu'à ~10-12 SA. Ensuite, le placenta produit suffisamment de progestérone pour maintenir la grossesse.","s":3},{"q":"La barrière hémato-testiculaire est formée par :","o":["Cellules de Leydig","Jonctions serrées entre cellules de Sertoli","Tunique albuginée","Endothélium"],"r":1,"e":"La barrière hémato-testiculaire (jonctions serrées entre cellules de Sertoli) protège les spermatozoïdes (cellules haploïdes étrangères au système immunitaire) d'une réaction auto-immune.","s":3},{"q":"L'aromatase :","o":["Convertit le glucose en glycogène","Convertit les androgènes en œstrogènes (cellules de la granulosa, tissu adipeux)","Détruit les œstrogènes","Active la testostérone"],"r":1,"e":"Aromatase : enzyme qui convertit androgènes (testostérone, androstènedione) → œstrogènes (E2, E1). Présente dans granulosa, tissu adipeux, etc. Cible des inhibiteurs (cancer du sein hormonodépendant).","s":3},{"q":"Le spermatozoïde se compose de :","o":["Tête (ADN + coiffe enzymatique)","Partie médiane (riche en mitochondries)","Queue (microtubules)","Vitellus","Flagelle"],"r":[0,1,2,4],"e":"Tête (ADN), partie médiane (mitochondries = ATP), queue/flagelle (locomotion). Le vitellus est dans l'ovule.","s":3},{"q":"Le vitellus est :","o":["Une enzyme du sperme","Les réserves nutritives de l'ovule jusqu'à l'implantation","Une hormone","Un type de spermatozoïde"],"r":1,"e":"Vitellus = réserves nutritives de l'ovule, nourrit l'embryon jusqu'à l'implantation.","s":3},{"q":"La spermatogenèse a lieu dans :","o":["L'épididyme","Les tubules séminifères des testicules","La prostate","Les vésicules séminales"],"r":1,"e":"Spermatogenèse dans les tubules séminifères des testicules.","s":3},{"q":"Les cellules de Sertoli :","o":["Nourrissent les cellules germinales","Sécrètent l'inhibine","Produisent la testostérone","Contrôlent les cellules germinales"],"r":[0,1,3],"e":"Sertoli : nourricières + sécrètent inhibine (rétro FSH). La testostérone vient des cellules de Leydig.","s":3},{"q":"Les cellules de Leydig produisent :","o":["L'inhibine","La testostérone","La LH","Les spermatozoïdes"],"r":1,"e":"Cellules de Leydig (interstitielles) = production de testostérone, stimulées par LH.","s":3},{"q":"L'ovocyte II est bloqué en méiose II en :","o":["Prophase II","Métaphase II (débloquée par fécondation)","Anaphase II","Telophase II"],"r":1,"e":"Ovocyte II bloqué en métaphase II ; débloqué par la pénétration du spermatozoïde → ovule + 2e corps polaire.","s":3},{"q":"FSH agit sur :","o":["Cellules de Leydig → testostérone","Cellules de Sertoli → spermatogenèse","Hypothalamus","Glandes surrénales"],"r":1,"e":"FSH stimule cellules de Sertoli → développement des spermatozoïdes (synergie avec testostérone).","s":3},{"q":"La phase lutéale du cycle féminin dure :","o":["Variable selon la longueur du cycle","6 à 16 jours","Constamment 14 jours","21 jours"],"r":2,"e":"Phase lutéale = constante 14 jours. Seule la phase folliculaire varie (6-16 jours).","s":3},{"q":"Le déclencheur de l'ovulation est :","o":["Un pic de FSH","Un pic de LH","Une chute de progestérone","Un pic d'œstrogènes seul"],"r":1,"e":"Ovulation : pic de LH (déclenché par rétroaction positive des œstrogènes en fin de phase folliculaire).","s":3},{"q":"Les vésicules séminales contribuent au sperme à hauteur de :","o":["10%","30%","60%","90%"],"r":2,"e":"Vésicules séminales = 60% du sperme, contenu visqueux et alcalin (fructose, prostaglandines).","s":3},{"q":"La prostate sécrète :","o":["Acide citrique (Krebs)","Enzymes protéolytiques (décoagulation)","Zinc (stabilise ADN)","Fructose","Plasma séminal antibiotique"],"r":[0,1,2,4],"e":"Prostate (~30% sperme, pH 6,5) : acide citrique, enzymes décoagulantes, zinc, plasma antibiotique. Fructose = vésicules séminales.","s":3},{"q":"Le pH final du sperme est :","o":["Acide (~5,5)","Légèrement acide (~6,5)","Alcalin (~7,2-7,7)","Neutre (~7,0)"],"r":2,"e":"pH final ~7,2-7,7 (alcalin) malgré l'acidité de la prostate, grâce au volume et à l'alcalinité des vésicules séminales.","s":3},{"q":"La partie médiane du spermatozoïde est :","o":["Riche en mitochondries, source d'énergie","Porteuse de l'ADN","Faite de microtubules de locomotion","Riche en vitellus"],"r":0,"e":"La tête contient l'ADN sous une coiffe riche en enzymes, et la queue les microtubules de locomotion.","s":3},{"q":"Le vitellus de l'ovule :","o":["Nourrit l'embryon jusqu'à l'implantation","Assure la mobilité","Contient l'ADN","Produit les hormones"],"r":0,"e":"C'est la réserve nutritive qui explique la grande taille de l'ovule.","s":3},{"q":"La spermiogenèse correspond à l'étape :","o":["Des spermatides vers les spermatozoïdes","De la spermatogonie vers le spermatocyte I","De la méiose I","De la méiose II"],"r":0,"e":"Elle achève la spermatogenèse dans les tubules séminifères.","s":3},{"q":"L'ovocyte I est bloqué :","o":["En prophase I, avant la naissance, et reprend à la puberté","En métaphase II","En anaphase I","En télophase"],"r":0,"e":"L'ovocyte II est ensuite bloqué en métaphase II, débloqué par la pénétration du spermatozoïde.","s":3},{"q":"Le mécanisme hormonal de la puberté associe :","o":["Une diminution de sensibilité de l'hypothalamus et de l'hypophyse à la rétroaction négative et une augmentation de sensibilité des gonades à FSH et LH","Une seule baisse de sensibilité","Une seule hausse","Aucun changement de sensibilité"],"r":0,"e":"Il en résulte une augmentation de LH et FSH, la croissance des gonades et la gamétogenèse.","s":3},{"q":"Parmi les facteurs influençant la puberté, le cours cite comme facteur majeur :","o":["La nutrition","La génétique","L'environnement","Le stress psychologique"],"r":0,"e":"Les quatre facteurs cités sont la génétique, l'environnement, le stress psychologique et la nutrition.","s":3},{"q":"La ménarche survient :","o":["Entre 11 et 13 ans, et s'achève vers 16 ans","Entre 8 et 10 ans","Entre 14 et 16 ans","Après 16 ans"],"r":0,"e":"La puberté masculine survient entre 12 et 14 ans avec l'augmentation de la testostérone.","s":3},{"q":"Parmi les sept effets de la testostérone figure :","o":["L'augmentation de l'érythropoïèse, d'environ 20 % de globules rouges","Une baisse du métabolisme","Une diminution de la masse musculaire","Une peau plus fine"],"r":0,"e":"S'y ajoutent croissance capillaire, peau plus rugueuse, sécrétion sébacée, hypertrophie du larynx, métabolisme de base et synthèse protéique.","s":3},{"q":"Quelle est l'unité contractile du muscle squelettique ?","o":["La myofibrille","Le sarcomère","La fibre musculaire","Le fascicule"],"r":1,"e":"Le sarcomère est l'unité contractile (entre 2 stries Z), composé de filaments épais (myosine) et fins (actine).","s":4},{"q":"VO₂max correspond à :","o":["Volume d'O₂ inhalé au repos","Consommation maximale d'O₂ pendant l'exercice intense","Pression d'O₂ artérielle","Saturation de l'hémoglobine"],"r":1,"e":"VO₂max = consommation maximale d'oxygène utilisable. Exprimé en ml/kg/min. Meilleur marqueur de l'aptitude aérobie.","s":4},{"q":"Le débit cardiaque au repos est environ :","o":["1 L/min","5 L/min","20 L/min","50 L/min"],"r":1,"e":"Débit cardiaque au repos ≈ 5 L/min (FC × VES = 70 × 70 ml). À l'exercice maximal : 25–30 L/min.","s":4},{"q":"Combien de temps dure le système ATP-PCr (phosphagène) ?","o":["~10 secondes (efforts explosifs)","30 minutes","1 heure","Indéfiniment"],"r":0,"e":"Le système ATP-phosphocréatine fournit de l'énergie ~10 secondes (sprints, haltérophilie). Régénère rapidement l'ATP sans O₂.","s":4},{"q":"L'eau dans l'organisme représente quel pourcentage du poids ?","o":["20%","60%","80%","100%"],"r":1,"e":"L'eau corporelle ≈ 60% du poids (variable selon âge, sexe, masse grasse). Très importante pour la thermorégulation à l'effort.","s":4},{"q":"La principale méthode de thermorégulation à l'exercice est :","o":["Frissons","Vasoconstriction cutanée","Vasodilatation cutanée + sudation (évaporation)","Augmentation du métabolisme"],"r":2,"e":"Effort = production massive de chaleur. Évacuation par : vasodilatation cutanée + sudation (évaporation = principal mécanisme).","s":4},{"q":"L'hydratation pré-exercice recommandée est :","o":["100 ml","600–800 ml dans les 10–15 min avant l'effort","3 L à boire d'un coup","Aucune eau"],"r":1,"e":"Préhydratation : 600–800 ml d'eau 10–15 min avant l'effort. Pendant : petites quantités toutes les 10–15 min.","s":4},{"q":"Pour la population générale, la répartition glucides/lipides/protéines est :","o":["20/60/20","50/30/15 (le reste fibres)","10/10/80","100% protéines"],"r":1,"e":"Population générale : ~50% glucides, ~30% lipides, ~15% protéines. Privilégier glucides complexes et lipides insaturés.","s":4},{"q":"Le sportif doit avoir une alimentation :","o":["Identique au sédentaire","Plus riche en glucides (60–70%) pour le glycogène musculaire","Sans glucides","Riche en alcool"],"r":1,"e":"Sportif : 60–70% glucides (glycogène musculaire), ~12% protéines. Vigilance fer et calcium.","s":4},{"q":"Quelle est la principale source d'énergie immédiate (1ères secondes) ?","o":["Glycolyse anaérobie","Phosphocréatine (ATP-PCr)","Phosphorylation oxydative","β-oxydation"],"r":1,"e":"Le système ATP-PCr (phosphagène) fournit l'énergie pendant les ~10 premières secondes : la créatine phosphate régénère rapidement l'ATP.","s":4},{"q":"La glycolyse anaérobie produit comme déchet :","o":["Eau et CO₂","Acide lactique (lactate)","Ammoniac","Corps cétoniques"],"r":1,"e":"Glycolyse anaérobie : glucose → pyruvate → lactate. Alimente les efforts intenses 30 sec à 2 min. Le lactate participe à la fatigue.","s":4},{"q":"Pour un effort modéré prolongé (>30 min), la principale filière est :","o":["Phosphocréatine","Glycolyse anaérobie","Métabolisme aérobie (oxydation glucides puis lipides)","Protéolyse"],"r":2,"e":"Effort prolongé modéré : métabolisme aérobie. Oxydation glucides (glycogène) puis recours croissant aux lipides (β-oxydation).","s":4},{"q":"L'augmentation du débit cardiaque à l'effort est due à :","o":["FC seule","VES seul","Augmentation de FC ET de VES","Diminution des résistances"],"r":2,"e":"Q = FC × VES. À l'effort : passage de 5 → 25-30 L/min par ↑ FC (jusqu'à FCmax ≈ 220-âge) et ↑ VES (jusqu'à plateau).","s":4},{"q":"L'EPOC (dette d'oxygène) est :","o":["Un manque permanent d'O₂","La consommation excédentaire d'O₂ après l'effort pour rétablir l'homéostasie","Le déficit en hémoglobine","L'O₂ stocké dans la myoglobine"],"r":1,"e":"EPOC : consommation d'O₂ qui reste élevée après l'effort. Sert à : régénérer phosphagènes, métaboliser le lactate, restaurer myoglobine, thermorégulation.","s":4},{"q":"Le flux sanguin à l'effort est redirigé :","o":["Vers le tube digestif","Vers les muscles actifs et la peau (au détriment des viscères)","Vers le cerveau seul","Réduit globalement"],"r":1,"e":"Effort : vasodilatation musculaire + vasoconstriction splanchnique → muscles actifs reçoivent jusqu'à 80% du débit. Peau aussi pour thermorégulation.","s":4},{"q":"Pendant l'exercice, la ventilation peut atteindre :","o":["6 L/min seulement","20 L/min","100 L/min","1000 L/min"],"r":2,"e":"Ventilation au repos = 6 L/min. À l'effort intense : jusqu'à 100 L/min (×15-20). Augmentation par ↑ fréquence + ↑ volume courant (athlète favorise VT).","s":4},{"q":"La FC max théorique se calcule par :","o":["220 − âge","100 − âge","Âge × 2","Toujours 200"],"r":0,"e":"Formule classique : FCmax ≈ 220 − âge (estimation, ±10-15 bpm de variation interindividuelle).","s":4},{"q":"Quel hormone augmente fortement à l'effort pour mobiliser glycogène et lipides ?","o":["Insuline","Adrénaline (et noradrénaline)","ADH","Aldostérone"],"r":1,"e":"Catécholamines (adré, noradré) ↑ à l'effort : ↑ FC, ↑ contractilité, glycogénolyse (mobilise glycogène), lipolyse (mobilise lipides). Insuline ↓.","s":4},{"q":"L'entraînement aérobie au long cours entraîne au repos :","o":["FC ↑ (tachycardie)","FC ↓ (bradycardie d'entraînement) + VES ↑","VES ↓","HTA"],"r":1,"e":"Entraînement endurance : bradycardie de repos (<60 bpm chez l'athlète) car le VES augmente. Le débit cardiaque de repos reste constant.","s":4},{"q":"Une adaptation typique de l'entraînement en endurance est :","o":["Hypertrophie massive","↑ mitochondries, capillaires, myoglobine, enzymes oxydatives","↓ VO₂max","Conversion fibres I → IIb"],"r":1,"e":"Aérobie : ↑ nombre/taille des mitochondries, densité capillaire musculaire, myoglobine, enzymes oxydatives, VO₂max. Le diamètre musculaire change peu.","s":4},{"q":"VO₂max chez un jeune adulte moyen est :","o":["10 ml/kg/min","~50 ml/kg/min","100 ml/kg/min","Variable inconnu"],"r":1,"e":"VO₂max moyen jeune adulte ≈ 50 ml/kg/min. Athlète d'endurance : 70-90 ml/kg/min. Sédentaire : 30-40.","s":4},{"q":"L'effet presseur de l'exercice est :","o":["Baisse de la PA","Augmentation de la PA (surtout systolique), plus marquée pour les membres supérieurs","PA stable","Hypotension"],"r":1,"e":"Effet presseur : ↑ PA systolique à l'exercice (+50-100 mmHg). Plus marqué pour les membres supérieurs (masse musculaire moindre, vasoconstriction). PA diastolique stable ou ↓.","s":4},{"q":"La triade musculaire est :","o":["Trois sarcomères","Tubule T + 2 citernes du réticulum sarcoplasmique","Trois fibres musculaires","Actine + myosine + tropomyosine"],"r":1,"e":"Triade = jonction tripartite : 1 tubule T (invagination membranaire) + 2 citernes terminales du réticulum sarcoplasmique. Permet le couplage excitation-contraction.","s":4},{"q":"Quel ion déclenche la contraction musculaire ?","o":["Na⁺","K⁺","Ca²⁺ (libéré par le RS)","Mg²⁺"],"r":2,"e":"Le PA → tubule T → ouverture canaux Ca²⁺ du RS → libération Ca²⁺ dans le cytosol → fixation sur troponine → glissement des filaments → contraction.","s":4},{"q":"Le seuil anaérobie (lactique) correspond à :","o":["L'absence d'O₂","L'intensité au-delà de laquelle le lactate s'accumule plus vite qu'il n'est éliminé","Le VO₂max","Le repos"],"r":1,"e":"Seuil lactique : intensité où la production de lactate dépasse sa clairance → accumulation. Survient à ~50-70% du VO₂max chez le sédentaire, plus haut chez l'athlète. Marqueur clé d'endurance.","s":4},{"q":"Le quotient respiratoire (QR) au repos est environ :","o":["0,2","~0,8 (mélange glucides + lipides)","1,5","5"],"r":1,"e":"QR = VCO₂/VO₂. ~1,0 si glucides purs, ~0,7 si lipides purs. Au repos : ~0,8 (mélange). À l'effort intense : tend vers 1,0 (glucides dominants).","s":4},{"q":"Au-delà du VO₂max, l'énergie supplémentaire provient de :","o":["L'aérobie","Le métabolisme anaérobie (~10–20% à la vitesse du VO₂max)","Le repos","Aucune source"],"r":1,"e":"Au-delà du VO₂max, poumons/cœur/muscles ont atteint leur limite. L'effort supplémentaire est couvert par le métabolisme anaérobie (lactate).","s":4},{"q":"Les fibres musculaires de type I sont :","o":["Rapides, glycolytiques, fatiguent vite","Lentes, oxydatives, riches en mitochondries et myoglobine, résistantes à la fatigue","Inexistantes","Identiques aux IIb"],"r":1,"e":"Type I : lentes, oxydatives, rouges (myoglobine), nombreuses mitochondries, résistantes à la fatigue. Marathon. Type IIa : intermédiaires. Type IIb/IIx : rapides, glycolytiques, fatiguent vite. Sprint.","s":4},{"q":"Le déficit en O₂ correspond à :","o":["Une asphyxie","La non-utilisation d'O₂ au début de l'effort (avant stabilisation du VO₂)","L'EPOC","Un manque génétique"],"r":1,"e":"Déficit en O₂ : au début d'un effort, le métabolisme aérobie n'est pas encore à son régime → recours au système anaérobie. Plus faible chez l'athlète entraîné (stabilisation rapide).","s":4},{"q":"Le couplage excitation-contraction implique :","o":["Aucune protéine","PA → DHPR (tubule T) → RyR (RS) → libération Ca²⁺ → fixation troponine → glissement filaments","Diffusion simple","Endocytose"],"r":1,"e":"PA propagé par tubule T → activation DHPR (canal voltage-dépendant) → ouverture du récepteur RyR du RS → libération massive de Ca²⁺ → fixation sur troponine C → déplacement de la tropomyosine → contraction.","s":4},{"q":"L'organisation hiérarchique du muscle inclut :","o":["Muscle entier (épimysium)","Fascicule (périmysium)","Fibre musculaire (endomysium)","Myofibrille (sarcomères)","Filaments d'actine et myosine","Le motoneurone alpha et sa plaque motrice"],"r":[0,1,2,3,4],"e":"Hiérarchie : muscle (épimysium) → fascicule (périmysium) → fibre (endomysium) → myofibrille → filaments épais (myosine) + fins (actine). Le motoneurone appartient au système nerveux : c'est l'unité fonctionnelle de commande, pas un niveau de l'emboîtement structural du muscle.","s":4},{"q":"La triade musculaire correspond à :","o":["3 sarcomères alignés","Tubule T + 2 citernes du réticulum sarcoplasmique","3 mitochondries","3 noyaux"],"r":1,"e":"Triade = 1 tubule T + 2 citernes terminales du RS, jonction tripartite, transmet le PA pour libérer le Ca²⁺.","s":4},{"q":"Le débit cardiaque maximal à l'exercice atteint :","o":["10 L/min","15-20 L/min","25-30 L/min","50 L/min"],"r":2,"e":"DC max ~25-30 L/min (×5-6 par rapport au repos à 5 L/min).","s":4},{"q":"La FC d'un athlète au repos vs effort suit un facteur :","o":["×2","×4","×6","×10"],"r":2,"e":"Athlète : FC max ≈ 6× FC repos. Personne normale : ≈ 4×.","s":4},{"q":"Pour un sportif, la répartition glucides est :","o":["30-40%","50%","60-70%","80-90%"],"r":2,"e":"Sportif : 60-70% glucides (glycogène musculaire), 12% protéines.","s":4},{"q":"La préhydratation recommandée 10-15 min avant l'effort est :","o":["100-200 mL","300-400 mL","600-800 mL","1500 mL"],"r":2,"e":"Préhydratation : 600-800 mL chez l'adulte, 10-15 min avant l'effort.","s":4},{"q":"Le volume courant à l'exercice se stabilise à :","o":["~30% de la capacité vitale","~60% de la capacité vitale","~90% de la capacité vitale","100%"],"r":1,"e":"VT plafonne à ~60% de la capacité vitale ; au-delà, c'est la fréquence qui augmente.","s":4},{"q":"L'hyperpnée d'exercice maintient :","o":["PO2 et PCO2 stables","Une hypocapnie","Une acidose","Une hyperoxie"],"r":0,"e":"L'hyperpnée d'exercice ne modifie ni PO2, PCO2, ni [H+] plasmatique → maintien de l'homéostasie.","s":4},{"q":"L'effet presseur de l'exercice est plus marqué pour :","o":["Les membres inférieurs","Les membres supérieurs","Le tronc","Identique partout"],"r":1,"e":"Effet presseur (↑ TA) plus marqué pour les exercices avec membres supérieurs.","s":4},{"q":"VO₂max relatif s'exprime en :","o":["L/min","mL/min","mL/kg/min","mL/m²"],"r":2,"e":"VO₂max relatif = mL/kg/min (corrige la masse) ; absolu = L/min.","s":4},{"q":"La phase I de la réponse hyperpnéique débute :","o":["Après 1 minute","Avec un délai de 30 secondes","Brusquement dès le début, via cortex cérébral","Après le seuil lactique"],"r":2,"e":"Phase I : ↑ brusque dès le début, anticipée par le cortex cérébral → centre respiratoire (tronc cérébral).","s":4},{"q":"En cas de chaleur et humidité élevées, le risque principal est :","o":["L'hypothermie","Le coup de chaleur","La déshydratation seule","La crampe"],"r":1,"e":"Chaleur + humidité élevées → la transpiration ne suffit plus → coup de chaleur, refroidissement artificiel nécessaire.","s":4},{"q":"Le fascicule musculaire est entouré par :","o":["Le périmysium","L'épimysium","L'endomysium","Le sarcolemme"],"r":0,"e":"L'épimysium entoure le muscle entier et l'endomysium la fibre musculaire.","s":4},{"q":"La plasticité des fibres musculaires permet :","o":["La conversion entre types de fibres, l'hypertrophie et l'augmentation de la densité mitochondriale","La seule hypertrophie","La seule conversion de fibres","Aucune adaptation"],"r":0,"e":"C'est le fondement physiologique de l'adaptation à l'entraînement.","s":4},{"q":"L'alimentation du sportif comporte une part protéique de :","o":["12 %","15 %","20 %","30 %"],"r":0,"e":"Les glucides y montent à 60-70 %, contre 50 % en population générale ; le fer et le calcium demandent une attention particulière.","s":4},{"q":"La part de graisses saturées recommandée est :","o":["Au maximum 10 %","30 %","15 %","Sans limite"],"r":0,"e":"Les lipides insaturés sont à privilégier, dans un total lipidique de 30 % pour la population générale.","s":4},{"q":"L'alcool est déconseillé car il apporte :","o":["Des calories vides et agit comme diurétique, favorisant la déshydratation","Des glucides rapides","Des protéines","Des lipides"],"r":0,"e":"La modération du sel est par ailleurs recommandée, surtout en cas d'hypertension.","s":4},{"q":"La préhydratation recommandée 10 à 15 minutes avant l'effort est de :","o":["600 à 800 mL chez l'adulte","200 mL","1,5 L","300 mL"],"r":0,"e":"Pendant l'effort, il faut boire de petites quantités toutes les 10 à 15 minutes.","s":4},{"q":"Le débit musculaire au repos représente :","o":["15 à 20 % du débit cardiaque, et atteint 15 à 20 L/min à l'effort","50 % du débit cardiaque","5 %","80 %"],"r":0,"e":"C'est une multiplication par 20 du débit musculaire absolu.","s":4},{"q":"La fréquence cardiaque de l'athlète, du repos à l'effort, est multipliée par :","o":["6, contre 4 chez une personne normale","2","4, comme chez tout le monde","10"],"r":0,"e":"Sa fréquence de repos plus basse lui donne une réserve plus grande.","s":4},{"q":"Combien de stades de sommeil distingue-t-on ?","o":["2 (calme et agité)","3","4-5 stades : sommeil lent (3-4 stades) + sommeil paradoxal (REM)","Une seule phase"],"r":2,"e":"Sommeil = lent (NREM, stades N1, N2, N3) + paradoxal (REM). Cycle ~90 min, répété 4-6× par nuit.","s":5},{"q":"Quelle hormone régule le rythme veille-sommeil ?","o":["Cortisol","Mélatonine (pinéale, sécrétée la nuit)","Insuline","TSH"],"r":1,"e":"Mélatonine : sécrétée par la pinéale en l'absence de lumière (nuit). Synchronise le rythme circadien et favorise l'endormissement. Inhibée par la lumière.","s":5},{"q":"Le rythme circadien dure environ :","o":["12 heures","24 heures","48 heures","1 semaine"],"r":1,"e":"Rythme circadien ≈ 24h (en réalité ~24h11 min recalibré chaque jour par la lumière). Horloge maître = noyau suprachiasmatique de l'hypothalamus.","s":5},{"q":"L'hormone du stress qui pic le matin est :","o":["Mélatonine","Cortisol (pic 6-9h pour le réveil)","Insuline","Progestérone"],"r":1,"e":"Cortisol : pic matinal (6-9h) pour préparer au réveil et à l'activité. Diminue progressivement, nadir vers minuit. Antagoniste de la mélatonine.","s":5},{"q":"La température centrale est régulée autour de :","o":["35°C","36-37°C","38-39°C","40°C"],"r":1,"e":"Température centrale = 36,5-37,5°C, régulée par l'hypothalamus. Suit un rythme circadien (min ~4h, max ~17-19h). >38°C = fièvre.","s":5},{"q":"L'organisme est composé de combien de systèmes principaux ?","o":["3","5","11 (nerveux, endocrinien, cardiovasculaire, respiratoire, immunitaire, digestif, urinaire, musculaire, squelettique, tégumentaire, reproducteur)","20"],"r":2,"e":"11 systèmes organiques principaux. Travaillent ensemble pour maintenir l'homéostasie. Beaucoup d'organes contribuent à plusieurs systèmes.","s":5},{"q":"L'horloge biologique principale se trouve dans :","o":["Le cœur","Le foie","Le noyau suprachiasmatique de l'hypothalamus","L'estomac"],"r":2,"e":"Le noyau suprachiasmatique (NSC) de l'hypothalamus est l'horloge maître. Reçoit l'info lumineuse via le tract rétino-hypothalamique.","s":5},{"q":"Quelle glande sécrète la mélatonine ?","o":["Hypothalamus","Glande pinéale (épiphyse)","Hypophyse","Surrénale"],"r":1,"e":"La glande pinéale (épiphyse) sécrète la mélatonine sous contrôle du NSC : pic ≈ 2h, début ≈ 21h, arrêt ≈ 7h30.","s":5},{"q":"Combien d'heures de sommeil sont recommandées pour un adulte ?","o":["3-4 heures","5-6 heures","7-9 heures","12-14 heures"],"r":2,"e":"Adulte : 7-9 heures de sommeil/nuit recommandées. Variabilité individuelle. Privation chronique = effets délétères cognitifs, cardiométaboliques, immunitaires.","s":5},{"q":"Le rôle physiologique principal du sommeil paradoxal (REM) est :","o":["Récupération musculaire","Consolidation de la mémoire et régulation émotionnelle (rêves intenses)","Élimination des déchets","Croissance osseuse"],"r":1,"e":"REM (mouvements oculaires rapides) : rêves vifs, consolidation mémoire (procédurale, émotionnelle), traitement émotionnel. Atonie musculaire mais activité cérébrale intense.","s":5},{"q":"Le mécanisme principal de thermorégulation en cas de chaleur est :","o":["Frissons","Vasoconstriction cutanée","Vasodilatation cutanée + sudation","↑ métabolisme"],"r":2,"e":"Chaleur : hypothalamus → vasodilatation cutanée (transfert thermique) + sudation (évaporation = principal mécanisme). Froid : vasoconstriction + frissons.","s":5},{"q":"Le débit sanguin postprandial est augmenté vers :","o":["Les muscles","Le tube digestif (somnolence postprandiale)","Le cerveau","Les reins"],"r":1,"e":"Postprandial : sang redirigé vers le tube digestif (jusqu'à 30% du DC) pour absorption → d'où la somnolence et la contre-indication d'effort intense après repas copieux.","s":5},{"q":"Le stress aigu active le système :","o":["Parasympathique","Sympathique (catécholamines : ↑ FC, ↑ PA)","Endocrinien thyroïdien seul","Aucun"],"r":1,"e":"Stress aigu = activation sympathique (« fight or flight ») : libération adré/noradré → ↑ FC, ↑ PA, ↑ contractilité, vasoconstriction splanchnique, vasodilatation musculaire.","s":5},{"q":"L'activité physique régulière diminue le risque de :","o":["Diabète, MCV, dépression, certains cancers","Croissance osseuse","Fonction cognitive","Densité musculaire"],"r":0,"e":"≥150 min/sem d'AP modérée → ↓ diabète T2, MCV, certains cancers (côlon, sein), dépression, démence, ostéoporose. Recommandations OMS.","s":5},{"q":"Pendant un jeûne prolongé (>24h), la principale source d'énergie est :","o":["Glycogène (épuisé)","Lipides (β-oxydation, corps cétoniques)","Glucose plasmatique","Lactate"],"r":1,"e":"Après ~24h, le glycogène hépatique est épuisé. L'organisme passe aux lipides : β-oxydation → corps cétoniques (utilisables par cerveau et muscles). Protéolyse limitée.","s":5},{"q":"Une privation chronique de sommeil entraîne :","o":["Aucune conséquence","Altération cognitive, immunodépression, ↑ risque cardiométabolique, troubles humeur","Amélioration de la performance","↓ FC seule"],"r":1,"e":"Privation chronique : ↓ attention/mémoire, immunodépression, résistance à l'insuline, prise de poids, ↑ MCV, ↑ dépression, ↓ performance physique.","s":5},{"q":"Le pic de l'hormone de croissance (GH) se produit :","o":["Au matin","Pendant le sommeil profond (N3)","À midi","À l'effort uniquement"],"r":1,"e":"GH : pic principal pendant le sommeil profond (N3). Rôle dans la réparation tissulaire et la croissance. Privation de sommeil = ↓ sécrétion GH.","s":5},{"q":"La leptine est :","o":["Hormone de la faim","Hormone de satiété, ↑ la nuit, ↓ le matin","Hormone du stress","Insuline-like"],"r":1,"e":"Leptine = hormone de satiété (sécrétée par le tissu adipeux). Niveaux nocturnes ↑, diminuent en début de journée. La privation de sommeil ↓ leptine et ↑ ghréline → faim accrue.","s":5},{"q":"Une élévation de la pression artérielle survient typiquement :","o":["Vers minuit","Le matin (montée rapide vers 6h45 → risque cardiovasculaire matinal)","Jamais","À 19h uniquement"],"r":1,"e":"PA : montée rapide vers 6h45 (cortisol, sympathique). Pic vers 18h30. Min vers 2h. C'est pourquoi la fréquence des AVC/IDM est plus élevée en matinée.","s":5},{"q":"La synthèse de mélatonine suit la voie :","o":["Tryptophane → 5-OH-Trp → sérotonine → NAS → mélatonine","Glucose → pyruvate","Cholestérol → testostérone","ATP → ADP"],"r":0,"e":"Tryptophane (AA) → 5-hydroxytryptophane → sérotonine → N-acétylsérotonine (NAS) → mélatonine. Synthèse stimulée par l'obscurité, inhibée par la lumière.","s":5},{"q":"Le décalage horaire (jet lag) est dû à :","o":["Une infection","Une désynchronisation entre l'horloge interne et le nouveau cycle jour/nuit","Un excès de mélatonine","Une déshydratation"],"r":1,"e":"Jet lag : désynchronisation NSC vs lumière externe lors d'un voyage transméridien. Effets sur sommeil, vigilance, digestion. Réajustement ~1 jour/fuseau.","s":5},{"q":"L'efficacité cardiovasculaire et la force musculaire sont maximales vers :","o":["6h","12h","17h","23h"],"r":2,"e":"Performances physiques (force, coordination, efficacité CV) maximales en fin d'après-midi (~17h), pic de température centrale ~19h. Min en début de matinée.","s":5},{"q":"Le diabète illustre l'interconnexion des systèmes en affectant :","o":["Un seul système","Endocrinien + immunitaire + cardiovasculaire + urinaire + nerveux","Le cerveau seul","Aucun système"],"r":1,"e":"Diabète : endocrinien (insuline) + immunitaire (cicatrisation) + urinaire (néphropathie) + cardiovasculaire (microangiopathie, AVC, IDM) + nerveux (neuropathie). Tout est interconnecté.","s":5},{"q":"La voie d'entrée de la lumière vers la mélatonine est :","o":["Cerveau seul","Rétine → tract rétino-hypothalamique → NSC → glande pinéale → mélatonine","Peau → foie","Inconscient"],"r":1,"e":"Lumière captée par la rétine (cônes, bâtonnets, cellules ganglionnaires intrinsèquement photosensibles) → tract rétino-hypothalamique → NSC → contrôle pinéale → mélatonine.","s":5},{"q":"Le SAD (Seasonal Affective Disorder) est lié à :","o":["Un excès de soleil","Diminution de la lumière (hiver) → ↑ mélatonine → trouble de l'humeur","Une infection saisonnière","Une carence en fer"],"r":1,"e":"SAD = dépression saisonnière (hiver). Liée à la diminution de la lumière → désynchronisation circadienne, ↑ mélatonine en journée. Traitement : luminothérapie.","s":5},{"q":"L'axe HPA (hypothalamo-hypophyso-surrénalien) en réponse au stress chronique :","o":["Diminue le cortisol","↑ cortisol soutenu → effets délétères (immunosuppression, syndrome métabolique, atrophie hippocampe)","N'a aucun effet","Augmente la mélatonine"],"r":1,"e":"Stress chronique → activation soutenue de l'axe CRH-ACTH-cortisol → effets nocifs : immunosuppression, ostéoporose, dépression, atrophie hippocampique, syndrome métabolique.","s":5},{"q":"La réponse de peur active rapidement :","o":["Le cortex préfrontal seul","L'amygdale → tronc cérébral → réponse sympathique en quelques ms","Le cervelet seul","Aucune voie"],"r":1,"e":"Peur : voie courte amygdale (analyse rapide) → réponse sympathique immédiate. Voie longue passe par le cortex pour analyse plus fine et contrôle de la réponse.","s":5},{"q":"La sénescence (vieillissement) implique :","o":["Aucun changement","↓ fonctions hormonales (testostérone, œstrogènes, GH), ↓ masse musculaire/osseuse, ↓ immunité, ↓ thermorégulation","Augmentation de tous les organes","Aucune perte"],"r":1,"e":"Vieillissement : sarcopénie (↓ masse musc), ostéoporose (↓ os), ↓ hormones sexuelles, ↓ GH, ↓ immunité, ↓ thermorégulation, ↓ fonction cognitive. D'où l'importance de l'AP régulière.","s":5},{"q":"Tumeurs ou ablation du NSC entraînent :","o":["Aucun effet","Désynchronisation majeure du cycle veille/sommeil","Hypertension","Diabète"],"r":1,"e":"Lésions du noyau suprachiasmatique → perte de l'horloge maître → désorganisation du cycle veille/sommeil et des autres rythmes circadiens (température, hormones).","s":5},{"q":"Les cycles infraradiens (>24h) incluent :","o":["Le rythme cardiaque","Le cycle menstruel (~28 jours), variations saisonnières (T3/T4, mélatonine)","La respiration","Le cycle veille-sommeil"],"r":1,"e":"Cycles infraradiens (durée > 24h) : cycle menstruel (~28j), variations saisonnières (T3/T4 plus basses en hiver, mélatonine plus élevée). Cycles ultradiens : <24h (impulsions hormonales, REM/NREM).","s":5},{"q":"Le pic de cortisol survient typiquement vers :","o":["2h du matin","9h","15h","21h"],"r":1,"e":"Cortisol : pic vers 9h (vigilance/métabolisme), minimum en milieu de nuit.","s":5},{"q":"Le pic de mélatonine survient vers :","o":["2h du matin","9h","15h","17h"],"r":0,"e":"Mélatonine : début ~21h, pic ~2h, arrêt ~7h30. Inhibée par la lumière.","s":5},{"q":"La température corporelle minimale est observée vers :","o":["2h","4h","9h","19h"],"r":1,"e":"Température min ~4h, pic max ~19h. La mélatonine ↑ quand la T° ↓.","s":5},{"q":"L'hormone de croissance (GH) atteint son pic :","o":["Au réveil","Pendant le sommeil profond","En milieu d'après-midi","Le soir"],"r":1,"e":"GH : pic pendant le sommeil profond (réparation tissulaire, croissance).","s":5},{"q":"La ghréline est :","o":["Une hormone de la satiété sécrétée par le tissu adipeux","Une hormone orexigène sécrétée surtout par l'estomac, qui s'élève avant les repas","Une hormone thyroïdienne","Un neurotransmetteur du sommeil paradoxal"],"r":1,"e":"La ghréline est le miroir de la leptine : produite par la muqueuse gastrique, son pic précède les repas et stimule l'appétit via l'hypothalamus. La privation de sommeil augmente la ghréline et abaisse la leptine, ce qui explique la prise de poids associée au manque de sommeil.","s":5},{"q":"L'efficacité cardiovasculaire et la force musculaire maximales sont vers :","o":["7h","12h","17h","22h"],"r":2,"e":"Performance physique max ~17h (efficacité cardio + force musculaire).","s":5},{"q":"Le temps de réaction le plus rapide est vers :","o":["10h","15h30","19h","23h"],"r":1,"e":"Temps de réaction le plus rapide ~15h30. Meilleure coordination ~14h30.","s":5},{"q":"Le syndrome général d'adaptation au stress (Selye) comprend :","o":["Alarme → Résistance → Épuisement","Choc → Fuite → Combat","Tension → Détente","Anxiété → Phobie → Trauma"],"r":0,"e":"3 phases : Alarme (réaction immédiate) → Résistance (adaptation) → Épuisement (les défenses sont dépassées).","s":5},{"q":"Le rythme circadien est synchronisé par :","o":["La lumière (jour/obscurité)","Les températures","Les biorythmes mensuels","Les rythmes saisonniers"],"r":0,"e":"Rythme circadien (24h) synchronisé principalement avec l'alternance lumière/obscurité.","s":5},{"q":"La période où le risque cardiovasculaire est maximal (montée brusque de TA) est :","o":["Vers 2h","Vers 6h45","Vers 14h","Vers 22h"],"r":1,"e":"Vers 6h45 : montée brutale de la TA → ↑ risque cardiovasculaire (infarctus matinal).","s":5},{"q":"L'arrêt de la sécrétion de mélatonine survient :","o":["Vers 21h","Vers 4h","Vers 7h30","Vers 12h"],"r":2,"e":"Mélatonine : début ~21h, pic ~2h, arrêt ~7h30 (réveil).","s":5},{"q":"Les 4 systèmes affectés par le diabète sont :","o":["Endocrinien (glycémie)","Immunitaire (cicatrisation)","Urinaire (lésions rénales)","Cardiovasculaire (lésions vasculaires, cécité)","Squelettique"],"r":[0,1,2,3],"e":"Diabète : affecte endocrinien (cause), immunitaire (cicatrisation), urinaire (rein), cardio (vaisseaux + rétine).","s":5},{"q":"Le principe fondamental de l'intégration des systèmes énonce que :","o":["Tous les systèmes travaillent ensemble et la plupart des organes contribuent à plus d'un système","Chaque organe n'appartient qu'à un système","Les systèmes sont indépendants","Seul le système nerveux coordonne"],"r":0,"e":"Le cerveau appartient ainsi aux systèmes nerveux et endocrinien, et le sternum aux systèmes squelettique, immunitaire et cardiovasculaire.","s":5},{"q":"Le système respiratoire participe, outre les échanges gazeux :","o":["À la régulation de la température","À la digestion","À la production de cellules sanguines","Au contrôle du pH urinaire"],"r":0,"e":"Le système cardiovasculaire y contribue également, en plus du transport des matériaux.","s":5},{"q":"Le système squelettique assure, outre le soutien et la protection :","o":["Le mouvement et la production de cellules sanguines","La digestion","L'immunité spécifique","La thermorégulation seule"],"r":0,"e":"Le système tégumentaire assure, lui, soutien, protection et régulation des liquides.","s":5},{"q":"Les impulsions, parmi les biorythmes, correspondent :","o":["À une libération hormonale en jets, sur des minutes ou des heures, comme l'insuline","Au cycle de 24 heures","Au cycle menstruel","Aux variations saisonnières"],"r":0,"e":"Les quatre types cités sont impulsions, rythme circadien, cycle mensuel et variations saisonnières.","s":5},{"q":"Parmi les variations saisonnières, le cours cite :","o":["Des valeurs basses de T3 et T4 en hiver et une mélatonine plus élevée en hiver","Une mélatonine plus basse en hiver","Des T3 et T4 élevées en hiver","Aucune variation"],"r":0,"e":"Ces cycles dépassent 24 heures et relèvent des rythmes infradiens.","s":5},{"q":"À 6 h 45, l'événement circadien marquant est :","o":["Une montée rapide de la pression artérielle, période de risque cardiovasculaire","Le pic de cortisol","L'arrêt de la mélatonine","La température minimale"],"r":0,"e":"L'arrêt de la sécrétion de mélatonine survient vers 7 h 30 et le pic de cortisol vers 9 h.","s":5},{"q":"La meilleure coordination survient vers :","o":["14 h 30","15 h 30","17 h","10 h"],"r":0,"e":"Le temps de réaction le plus rapide se situe vers 15 h 30 et l'efficacité cardiovasculaire maximale vers 17 h.","s":5},{"q":"La pression artérielle maximale survient vers :","o":["18 h 30","6 h 45","19 h","21 h"],"r":0,"e":"La température corporelle maximale survient vers 19 h et le début de la sécrétion de mélatonine vers 21 h.","s":5}]};
